(function (g) { const EVENTS = [{"pref": "北海道", "kind": "災い", "era": "中世", "year": 1456, "title": "コシャマインの戦い", "text": "志濃里で和人がアイヌの若者を刺したことから、首長コシャマインらが蜂起し、渡島半島の和人の館を次々に落とした。武田信広らが鎮めた。", "source_url": "https://kotobank.jp/word/コシャマインの戦い", "source_title": "コトバンク「コシャマインの戦い」（日本大百科全書・デジタル大辞泉）"}, {"pref": "北海道", "kind": "災い", "era": "江戸", "year": 1669, "title": "シャクシャインの戦い", "text": "松前藩との交易の条件が悪くなるなか、シブチャリを拠点にシャクシャインが蜂起し、戦いは蝦夷地の各地に広がった。和議の席で殺された。", "source_url": "https://kotobank.jp/word/シャクシャインの戦い", "source_title": "コトバンク「シャクシャインの戦い」（日本大百科全書・精選版日本国語大辞典）"}, {"pref": "北海道", "kind": "恵み", "era": "江戸", "year": 1854, "title": "箱館の開港", "text": "日米和親条約で箱館の開港が決まり、下田とともに日本で最初の開港場の一つとなった。", "source_url": "https://kotobank.jp/word/函館", "source_title": "コトバンク「函館」（日本大百科全書・改訂新版世界大百科事典）"}, {"pref": "北海道", "kind": "恵み", "era": "明治", "year": 1875, "title": "屯田兵の入植", "text": "ふだんは農業を営み、北の守りも担う屯田兵が札幌郊外の琴似に初めて入植した。その後、各地に兵村がつくられた。", "source_url": "https://kotobank.jp/word/屯田兵", "source_title": "コトバンク「屯田兵」（日本大百科全書・百科事典マイペディアほか）"}, {"pref": "北海道", "kind": "災い", "era": "昭和", "year": 1926, "title": "十勝岳噴火の泥流", "text": "5月に十勝岳が噴火し、雪を溶かしてできた泥流が麓の上富良野や美瑛の市街を襲い、多くの死者を出した。", "source_url": "https://kotobank.jp/word/十勝岳", "source_title": "コトバンク「十勝岳」（日本大百科全書・ブリタニカ国際大百科事典ほか）"}, {"pref": "北海道", "kind": "災い", "era": "昭和", "year": 1934, "title": "函館大火", "text": "函館は明治から何度も大火に見舞われてきたが、とくにこの年の大火の被害は大きかった。", "source_url": "https://kotobank.jp/word/函館", "source_title": "コトバンク「函館」（日本大百科全書）"}, {"pref": "新潟", "kind": "災い", "era": "平安", "year": 863, "title": "越中・越後の地震", "text": "越中・越後で大きな地震があり、山崩れや民家の倒壊、湧き水が起き、押しつぶされて亡くなった人が多く出た。", "source_url": "https://www.jishin.go.jp/main/yosokuchizu/chubu/p15_niigata.htm", "source_title": "地震調査研究推進本部「新潟県の地震活動の特徴」"}, {"pref": "新潟", "kind": "災い", "era": "中世", "year": 1502, "title": "越後南西部の地震", "text": "越後南西部で地震があり、越後の国府で家屋が倒れ、多くの死者が出た。", "source_url": "https://www.jishin.go.jp/main/yosokuchizu/chubu/p15_niigata.htm", "source_title": "地震調査研究推進本部「新潟県の地震活動の特徴」"}, {"pref": "新潟", "kind": "災い", "era": "中世", "year": 1578, "title": "御館の乱", "text": "上杉謙信の死後、養子の景勝と景虎が跡目を争い、越後の武士たちが二つに割れた。景虎が自刃し、景勝が国を固めた。", "source_url": "https://kotobank.jp/word/御館の乱", "source_title": "コトバンク「御館の乱」（改訂新版世界大百科事典・百科事典マイペディア）"}, {"pref": "新潟", "kind": "恵み", "era": "中世", "year": 1601, "title": "佐渡相川の金銀山", "text": "このころから佐渡の相川で金銀山の開発が本格化し、相川は鉱山町として町割りされ、奉行所も置かれた。", "source_url": "https://kotobank.jp/word/佐渡金山", "source_title": "コトバンク「佐渡金山」（日本大百科全書・百科事典マイペディア・旺文社日本史事典）"}, {"pref": "新潟", "kind": "災い", "era": "江戸", "year": 1751, "title": "宝暦の高田地震", "text": "越後・越中を大地震が襲い、高田城が壊れた。高田領を中心に多くの死者が出て、家屋の全壊や焼失も多かった。", "source_url": "https://www.jishin.go.jp/main/yosokuchizu/chubu/p15_niigata.htm", "source_title": "地震調査研究推進本部「新潟県の地震活動の特徴」"}, {"pref": "新潟", "kind": "災い", "era": "江戸", "year": 1828, "title": "三条地震", "text": "越後平野の中ほどで地震が起き、三条・見附・今町・与板などで家屋が倒れ、火災も出た。地割れから水や砂が噴き出したと記録される。", "source_url": "https://www.jishin.go.jp/main/yosokuchizu/chubu/p15_niigata.htm", "source_title": "地震調査研究推進本部「新潟県の地震活動の特徴」"}, {"pref": "新潟", "kind": "災い", "era": "明治", "year": 1868, "title": "北越戦争", "text": "戊辰戦争で長岡藩などが新政府軍と戦い、長岡城は奪われては取り返す攻防の末に落ちた。戦いは越後の中部・北部に広がった。", "source_url": "https://kotobank.jp/word/北越戦争", "source_title": "コトバンク「北越戦争」（改訂新版世界大百科事典・山川日本史小辞典ほか）"}, {"pref": "新潟", "kind": "恵み", "era": "明治", "year": 1869, "title": "新潟港の開港", "text": "日米修好通商条約で開港場とされた新潟港が、明治元年の暮れ（西暦では1869年の正月）に開港した。", "source_url": "https://kotobank.jp/word/新潟港", "source_title": "コトバンク「新潟港」（デジタル大辞泉）"}, {"pref": "新潟", "kind": "災い", "era": "大正", "year": 1922, "title": "大河津分水の通水", "text": "信濃川の水を日本海へ逃がす分水路が、明治の着工と中断を経て工事が再開され、1922年に通水した。", "source_url": "https://kotobank.jp/word/大河津分水", "source_title": "コトバンク「大河津分水」（世界大百科事典〈旧版〉の信濃川・黒埼町・河川計画の項）"}, {"pref": "新潟", "kind": "道がひらく", "era": "昭和", "year": 1931, "title": "清水トンネル開通と上越線全通", "text": "群馬との県境の谷川連峰を貫く清水トンネルが完成し、上越線が全通した。上野と新潟が短い道のりで結ばれた。", "source_url": "https://kotobank.jp/word/清水トンネル", "source_title": "コトバンク「清水トンネル」（山川日本史小辞典・改訂新版世界大百科事典ほか）"}, {"pref": "新潟", "kind": "災い", "era": "昭和", "year": 1945, "title": "長岡空襲", "text": "8月1日夜、B29の焼夷弾爆撃で長岡の市街地が焼け野原となり、学童を含む多くの市民が亡くなった。", "source_url": "https://www.soumu.go.jp/main_sosiki/daijinkanbou/sensai/situation/state/shinetsu_02.html", "source_title": "総務省「長岡市における戦災の状況（新潟県）」"}, {"pref": "群馬", "kind": "災い", "era": "平安", "year": 1108, "title": "天仁の浅間山大噴火", "text": "浅間山が大噴火し、火山灰や砂礫が上野国に降り積もって田畑が壊滅した。被害のため国の貢納が免除された。", "source_url": "https://kotobank.jp/word/浅間山", "source_title": "コトバンク「浅間山」（日本歴史地名大系・改訂新版世界大百科事典）"}, {"pref": "群馬", "kind": "恵み", "era": "中世", "year": 1333, "title": "新田義貞の挙兵", "text": "上野の新田義貞が兵を挙げて鎌倉へ攻め上り、北条氏を滅ぼした。", "source_url": "https://kotobank.jp/word/上野国", "source_title": "コトバンク「上野国」（世界大百科事典）"}, {"pref": "群馬", "kind": "災い", "era": "江戸", "year": 1783, "title": "天明の浅間山噴火", "text": "浅間山の大噴火で北関東に軽石や灰が降り、火砕流が鎌原村を埋めた。吾妻川は土石でふさがれ、鉄砲水が下流を襲った。", "source_url": "https://kotobank.jp/word/浅間山", "source_title": "コトバンク「浅間山」（改訂新版世界大百科事典「浅間焼け」ほか）"}, {"pref": "群馬", "kind": "恵み", "era": "明治", "year": 1872, "title": "富岡製糸場の操業開始", "text": "官営の富岡製糸場が操業を始め、各地から集まった工女がフランス人の指導で器械製糸を学んだ。", "source_url": "https://kotobank.jp/word/富岡製糸場", "source_title": "コトバンク「富岡製糸場」（日本大百科全書・改訂新版世界大百科事典ほか）"}, {"pref": "群馬", "kind": "道がひらく", "era": "昭和", "year": 1931, "title": "清水トンネル開通と上越線全通", "text": "新潟との県境を貫く清水トンネルが完成して上越線が全通し、群馬の山あいを抜けて上野と新潟が結ばれた。", "source_url": "https://kotobank.jp/word/清水トンネル", "source_title": "コトバンク「清水トンネル」（山川日本史小辞典・改訂新版世界大百科事典ほか）"}, {"pref": "群馬", "kind": "災い", "era": "昭和", "year": 1945, "title": "太田・高崎の空襲", "text": "2月に太田の飛行場と軍需工場への空襲から県内の本格的な空襲が始まり、終戦前夜の8月14日には高崎の町なかも焼けた。", "source_url": "https://www.soumu.go.jp/main_sosiki/daijinkanbou/sensai/situation/state/kanto_03.html", "source_title": "総務省「高崎市における戦災の状況（群馬県）」"}, {"pref": "京都", "kind": "行事", "era": "平安", "year": 869, "title": "祇園御霊会の始まり", "text": "疫病の退散を祈って鉾を立て、神泉苑へ送ったのが祇園祭の始まりと伝えられる（970年とする説もある）。", "source_url": "https://kotobank.jp/word/祇園祭", "source_title": "コトバンク「祇園祭」（日本大百科全書・改訂新版世界大百科事典・山川日本史小辞典ほか）"}, {"pref": "京都", "kind": "災い", "era": "中世", "year": 1467, "title": "応仁の乱", "text": "京都を主な戦場とする戦乱が十一年続き、京都は焼け野原となった。洛外の主な社寺のほとんども兵火にあった。", "source_url": "https://kotobank.jp/word/応仁の乱", "source_title": "コトバンク「応仁の乱」（日本大百科全書・ブリタニカ国際大百科事典ほか）"}, {"pref": "京都", "kind": "災い", "era": "中世", "year": 1536, "title": "天文法華の乱", "text": "比叡山延暦寺の衆徒らが京の法華一揆を攻め、日蓮宗の二十一か寺を焼いて宗徒を京から追った。", "source_url": "https://kotobank.jp/word/天文法華の乱", "source_title": "コトバンク「天文法華の乱」（精選版日本国語大辞典・山川日本史小辞典ほか）"}, {"pref": "京都", "kind": "災い", "era": "江戸", "year": 1788, "title": "天明の大火", "text": "鴨川の東から出た火が川を越えて広がり、洛中の町のほとんどと御所・二条城を焼いた。", "source_url": "https://kotobank.jp/word/天明の大火", "source_title": "コトバンク「天明の大火」（改訂新版世界大百科事典・百科事典マイペディア）"}, {"pref": "京都", "kind": "災い", "era": "江戸", "year": 1864, "title": "禁門の変", "text": "長州藩兵が御所の蛤御門付近で幕府方と戦い、戦火で京都の市中は大火となった。", "source_url": "https://kotobank.jp/word/禁門の変", "source_title": "コトバンク「禁門の変」（山川日本史小辞典・改訂新版世界大百科事典）"}, {"pref": "京都", "kind": "恵み", "era": "明治", "year": 1890, "title": "琵琶湖疏水の完成", "text": "琵琶湖の水を大津から長等山のトンネルで蹴上へ引く疏水が完成した。舟運・発電・灌漑・飲み水に使われた。", "source_url": "https://biwakososui-museum.city.kyoto.lg.jp/pdf/about/chronology.pdf", "source_title": "琵琶湖疏水記念館「年表」／コトバンク「琵琶湖疏水」（日本大百科全書）"}, {"pref": "京都", "kind": "道がひらく", "era": "大正", "year": 1912, "title": "京都市三大事業の完成", "text": "第二疏水と蹴上浄水場ができて上水道の供給が始まり、市電も営業を始めた（明治45年のこと）。", "source_url": "https://biwakososui-museum.city.kyoto.lg.jp/pdf/about/chronology.pdf", "source_title": "琵琶湖疏水記念館「年表」"}, {"pref": "京都", "kind": "災い", "era": "昭和", "year": 1927, "title": "北丹後地震", "text": "3月7日の夕方、丹後半島を震源とする大地震が起きた。夕食どきで火災が広がり、断層沿いの町村では家屋の多くが倒れた。", "source_url": "https://kotobank.jp/word/北丹後地震", "source_title": "コトバンク「北丹後地震」（日本大百科全書・最新地学事典ほか）"}, {"pref": "千葉", "kind": "災い", "era": "平安", "year": 1028, "title": "平忠常の乱", "text": "下総の平忠常が安房守を攻め、上総の国府を占拠した。三年余りの戦乱の末、源頼信に降った。", "source_url": "https://kotobank.jp/word/平忠常の乱", "source_title": "コトバンク「平忠常の乱」（改訂新版世界大百科事典・日本大百科全書）"}, {"pref": "千葉", "kind": "災い", "era": "中世", "year": 1538, "title": "第一次国府台合戦", "text": "下総の国府台で北条氏綱が足利義明・里見義堯を破り、北条氏が下総へ進出した。", "source_url": "https://kotobank.jp/word/国府台合戦", "source_title": "コトバンク「国府台合戦」（世界大百科事典〈旧版〉国府台の項）"}, {"pref": "千葉", "kind": "災い", "era": "中世", "year": 1564, "title": "第二次国府台合戦", "text": "国府台を占めた里見義弘が北条氏康・氏政に敗れた。のち上総の北半は北条方、上総南部と安房は里見方に分かれた。", "source_url": "https://kotobank.jp/word/国府台合戦", "source_title": "コトバンク「国府台合戦」（世界大百科事典〈旧版〉国府台・上総国の項）"}, {"pref": "千葉", "kind": "恵み", "era": "江戸", "year": 1661, "title": "野田の醤油づくり", "text": "寛文のころ、野田で茂木家・高梨家を中心に醤油の本格的な醸造が始まり、江戸川の舟運で江戸へ運ばれた。", "source_url": "https://kotobank.jp/word/野田醤油", "source_title": "コトバンク「野田醤油」（日本大百科全書・世界大百科事典〈旧版〉・事典日本の地域ブランド）"}, {"pref": "千葉", "kind": "災い", "era": "江戸", "year": 1703, "title": "元禄地震", "text": "関東南部を襲った大地震で、房総南部では家や田畑がつぶれ、土地が隆起した。九十九里などの沿岸を津波が襲った。", "source_url": "https://kotobank.jp/word/元禄地震", "source_title": "コトバンク「元禄地震」（改訂新版世界大百科事典・ブリタニカ国際大百科事典）"}, {"pref": "千葉", "kind": "道がひらく", "era": "明治", "year": 1894, "title": "総武鉄道の開業", "text": "私鉄の総武鉄道が佐倉までの区間で開業し、のちに両国から千葉・銚子までがつながった。", "source_url": "https://kotobank.jp/word/総武本線", "source_title": "コトバンク「総武本線」（改訂新版世界大百科事典・ブリタニカ国際大百科事典ほか）"}, {"pref": "千葉", "kind": "災い", "era": "昭和", "year": 1945, "title": "千葉空襲", "text": "6月10日の航空機工場への爆撃に続き、7月7日未明の「七夕空襲」で千葉の市街地が焼夷弾に焼かれた。", "source_url": "https://www.soumu.go.jp/main_sosiki/daijinkanbou/sensai/situation/state/kanto_07.html", "source_title": "総務省「千葉市における戦災の状況（千葉県）」"}, {"pref": "三重", "kind": "災い", "era": "平安", "year": 1096, "title": "永長の地震と津波", "text": "東海沖の巨大地震と考えられる地震が畿内・東海道を揺らし、伊勢では津波の被害が出た。", "source_url": "https://www.jishin.go.jp/main/yosokuchizu/kinki/p24_mie.htm", "source_title": "地震調査研究推進本部「三重県の地震活動の特徴」"}, {"pref": "三重", "kind": "災い", "era": "中世", "year": 1204, "title": "三日平氏の乱", "text": "平家滅亡からおよそ二十年後、伊賀・伊勢の平氏の残党が蜂起して守護を追い出したが、京から出た鎌倉方に鎮められた。", "source_url": "https://kotobank.jp/word/三日平氏の乱", "source_title": "コトバンク「三日平氏の乱」（改訂新版世界大百科事典・世界大百科事典〈旧版〉）"}, {"pref": "三重", "kind": "災い", "era": "中世", "year": 1498, "title": "明応地震", "text": "東海道沖の巨大地震で伊勢の沿岸を津波が襲い、大湊などで多くの人が溺れ、塩田も被害を受けた。", "source_url": "https://kotobank.jp/word/明応地震", "source_title": "コトバンク「明応地震」（改訂新版世界大百科事典）／地震調査研究推進本部「三重県の地震活動の特徴」"}, {"pref": "三重", "kind": "災い", "era": "中世", "year": 1579, "title": "天正伊賀の乱", "text": "伊賀の地侍たちの惣国一揆は織田信雄の攻撃を退けたが、1581年に信長の大軍に敗れ、多くの寺が焼かれた。", "source_url": "https://kotobank.jp/word/伊賀惣国一揆", "source_title": "コトバンク「伊賀惣国一揆」（改訂新版世界大百科事典・百科事典マイペディア）"}, {"pref": "三重", "kind": "災い", "era": "江戸", "year": 1707, "title": "宝永地震", "text": "南海トラフ沿いの巨大地震が起き、尾鷲付近では津波によって多くの死者と家屋の流失が出た。", "source_url": "https://www.jishin.go.jp/main/yosokuchizu/kinki/p24_mie.htm", "source_title": "地震調査研究推進本部「三重県の地震活動の特徴」"}, {"pref": "三重", "kind": "行事", "era": "江戸", "year": 1830, "title": "文政のお蔭参り", "text": "阿波から始まったお蔭参りが各地に広がり、人々が宮川の渡しを越えて伊勢へ向かった。", "source_url": "https://kotobank.jp/word/お蔭参り", "source_title": "コトバンク「お蔭参り」（改訂新版世界大百科事典・百科事典マイペディア）"}, {"pref": "三重", "kind": "災い", "era": "江戸", "year": 1854, "title": "伊賀上野地震", "text": "伊賀上野の近くで陸の地震が起きた。伊賀上野のほか、奈良や大和郡山でも大きな被害が出た。", "source_url": "https://www.jishin.go.jp/main/yosokuchizu/kinki/p24_mie.htm", "source_title": "地震調査研究推進本部「三重県の地震活動の特徴」"}, {"pref": "三重", "kind": "道がひらく", "era": "明治", "year": 1890, "title": "関西鉄道の四日市〜柘植間全通", "text": "四日市に本社を置いた関西鉄道が四日市〜柘植間を全通させ、近江の草津方面と結んだ。", "source_url": "https://kotobank.jp/word/関西鉄道", "source_title": "コトバンク「関西鉄道」（日本大百科全書・世界大百科事典〈旧版〉）"}, {"pref": "三重", "kind": "恵み", "era": "明治", "year": 1893, "title": "半円真珠の養殖成功", "text": "御木本幸吉が鳥羽の相島で半円真珠の養殖に成功した。のちに真円真珠もつくり出した。", "source_url": "https://kotobank.jp/word/御木本幸吉", "source_title": "コトバンク「御木本幸吉」（日本大百科全書・改訂新版世界大百科事典ほか）"}, {"pref": "三重", "kind": "恵み", "era": "明治", "year": 1899, "title": "四日市港の開港", "text": "廻船問屋の稲葉三右衛門による修築を経た四日市港が開港場に指定され、綿花や羊毛の輸入港として伸びた。", "source_url": "https://kotobank.jp/word/四日市港", "source_title": "コトバンク「四日市港」（世界大百科事典〈旧版〉・デジタル大辞泉プラス）"}, {"pref": "三重", "kind": "道がひらく", "era": "昭和", "year": 1931, "title": "大阪〜宇治山田の直通電車", "text": "参宮急行電鉄の山田線とつながり、大阪の上本町から宇治山田までを電車が結んだ。当時日本一の長距離電車とされた。", "source_url": "https://kotobank.jp/word/参宮急行電鉄", "source_title": "コトバンク「参宮急行電鉄」（世界大百科事典〈旧版〉）"}, {"pref": "三重", "kind": "恵み", "era": "昭和", "year": 1932, "title": "深谷水道の開削", "text": "英虞湾と外洋の行き来をよくする深谷水道が開かれ、その後、湾内の真珠養殖が急速に伸びた。", "source_url": "https://kotobank.jp/word/真珠養殖", "source_title": "コトバンク「真珠養殖」（世界大百科事典〈旧版〉英虞湾の項）"}, {"pref": "三重", "kind": "災い", "era": "昭和", "year": 1944, "title": "東南海地震", "text": "12月7日、戦時下に起きた巨大地震で県のほぼ全域が強く揺れ、熊野灘沿岸を大津波が襲った。", "source_url": "https://kotobank.jp/word/東南海地震", "source_title": "コトバンク「東南海地震」（百科事典マイペディア・日本大百科全書ほか）／地震調査研究推進本部「三重県の地震活動の特徴」"}, {"pref": "三重", "kind": "災い", "era": "昭和", "year": 1945, "title": "四日市空襲", "text": "6月18日、四日市は大きな空襲を受けた。町の中心はひと晩で焼け野原となり、800人を超える命が失われた。", "source_url": "https://www.soumu.go.jp/main_sosiki/daijinkanbou/sensai/situation/state/tokai_12.html", "source_title": "総務省「四日市市における戦災の状況（三重県）」"}, {"pref": "福岡", "kind": "災い", "era": "平安", "year": 1019, "title": "刀伊の入寇", "text": "海賊の船団が対馬・壱岐を襲い、筑前の怡土・志摩・早良郡に上陸した。大宰権帥藤原隆家と地元の武士が撃退した。", "source_url": "https://kotobank.jp/word/刀伊の入寇", "source_title": "コトバンク「刀伊の入寇」（日本大百科全書・改訂新版世界大百科事典ほか）"}, {"pref": "福岡", "kind": "災い", "era": "中世", "year": 1274, "title": "文永の役", "text": "元・高麗の軍が対馬・壱岐を経て博多湾岸に上陸した。日本の軍勢は苦戦したが、敵は船へ引き揚げて去った。", "source_url": "https://kotobank.jp/word/文永の役", "source_title": "コトバンク「文永の役」（山川日本史小辞典・精選版日本国語大辞典）"}, {"pref": "福岡", "kind": "災い", "era": "江戸", "year": 1732, "title": "享保の飢饉（子年の大変）", "text": "虫害による大凶作で筑前でも多くの餓死者が出た。この飢饉は「子年の大変」として語り継がれた。", "source_url": "https://kotobank.jp/word/筑前国", "source_title": "コトバンク「筑前国」（世界大百科事典）"}, {"pref": "福岡", "kind": "道がひらく", "era": "明治", "year": 1889, "title": "九州鉄道の開業", "text": "九州鉄道が博多〜千歳川間で開業し、のちに門司から南へ延びた。筑豊の石炭を運ぶ鉄道網も密になった。", "source_url": "https://kotobank.jp/word/九州鉄道", "source_title": "コトバンク「九州鉄道」（山川日本史小辞典・日本大百科全書）"}, {"pref": "福岡", "kind": "恵み", "era": "明治", "year": 1901, "title": "官営八幡製鉄所の操業開始", "text": "遠賀郡八幡村で官営の製鉄所が操業を始めた。遠賀川の舟運で筑豊の石炭を運べることが立地の利点とされた。", "source_url": "https://kotobank.jp/word/八幡製鉄所", "source_title": "コトバンク「八幡製鉄所」（日本歴史地名大系・改訂新版世界大百科事典ほか）"}, {"pref": "福岡", "kind": "恵み", "era": "大正", "year": 1920, "title": "八幡製鉄所争議", "text": "賃上げと労働時間の短縮を求めて製鉄所の労働者がストライキに入り、操業が止まった。争議は敗れたが、直後に八時間制が実現した。", "source_url": "https://kotobank.jp/word/八幡製鉄所争議", "source_title": "コトバンク「八幡製鉄所争議」（改訂新版世界大百科事典・百科事典マイペディア・山川日本史小辞典）"}, {"pref": "福岡", "kind": "災い", "era": "昭和", "year": 1945, "title": "福岡大空襲", "text": "6月19日深夜、B29の焼夷弾攻撃が約二時間続き、福岡市の繁華街など主な地域がほとんど焦土となった。", "source_url": "https://www.soumu.go.jp/main_sosiki/daijinkanbou/sensai/situation/state/kyushu_01.html", "source_title": "総務省「福岡市における戦災の状況（福岡県）」"}, {"pref": "高知", "kind": "災い", "era": "平安", "year": 887, "title": "仁和地震", "text": "南海トラフ沿いの巨大地震が起き、土佐の沿岸部では津波で多くの人が溺れ死んだ。", "source_url": "https://www.data.jma.go.jp/kochi/jishin_bosai/jishin_higai.html", "source_title": "高知地方気象台「高知県に被害を及ぼした主な地震」"}, {"pref": "高知", "kind": "災い", "era": "平安", "year": 1099, "title": "康和南海地震", "text": "南海沖の巨大地震で、土佐の田畑が広く海に沈んだ。津波もあったとみられる。", "source_url": "https://www.data.jma.go.jp/kochi/jishin_bosai/jishin_higai.html", "source_title": "高知地方気象台「高知県に被害を及ぼした主な地震」"}, {"pref": "高知", "kind": "災い", "era": "中世", "year": 1361, "title": "正平の地震", "text": "畿内・土佐・阿波を襲った南海トラフ沿いの巨大地震で、土佐も津波の被害を受けた。", "source_url": "https://www.data.jma.go.jp/kochi/jishin_bosai/jishin_higai.html", "source_title": "高知地方気象台「高知県に被害を及ぼした主な地震」"}, {"pref": "高知", "kind": "災い", "era": "中世", "year": 1601, "title": "浦戸一揆", "text": "関ヶ原で長宗我部氏の時代が終わり、山内一豊が浦戸城に入ると、旧臣の一領具足らが浦戸一揆を起こし、多くが討ち死にした。", "source_url": "https://kotobank.jp/word/土佐国", "source_title": "コトバンク「土佐国」（世界大百科事典）"}, {"pref": "高知", "kind": "恵み", "era": "江戸", "year": 1631, "title": "野中兼山の新田開発", "text": "家老野中兼山が藩政を執った時期に用水が開かれ、新田開発が進んで広い土地が灌漑された。", "source_url": "https://kotobank.jp/word/土佐国", "source_title": "コトバンク「土佐国」（世界大百科事典）"}, {"pref": "高知", "kind": "災い", "era": "江戸", "year": 1707, "title": "宝永地震", "text": "南海トラフ沿いの巨大地震で、土佐は主に津波によって多くの死者・行方不明者を出し、家屋の全壊・流失も多かった。", "source_url": "https://www.data.jma.go.jp/kochi/jishin_bosai/jishin_higai.html", "source_title": "高知地方気象台「高知県に被害を及ぼした主な地震」"}, {"pref": "高知", "kind": "災い", "era": "江戸", "year": 1854, "title": "安政南海地震", "text": "安政東海地震の翌日に安政南海地震が続き、土佐領内で多くの死者と家屋の全壊・流失・焼失が出た。", "source_url": "https://www.data.jma.go.jp/kochi/jishin_bosai/jishin_higai.html", "source_title": "高知地方気象台「高知県に被害を及ぼした主な地震」"}, {"pref": "高知", "kind": "道がひらく", "era": "大正", "year": 1924, "title": "高知線の開業", "text": "3月に須崎〜日下間で鉄道が開業し、同じ年の11月には高知まで延びた。", "source_url": "https://kotobank.jp/word/土讃線", "source_title": "コトバンク「土讃線」（改訂新版世界大百科事典・日本大百科全書）"}, {"pref": "高知", "kind": "道がひらく", "era": "昭和", "year": 1935, "title": "土讃線、四国山地を越える", "text": "豊永〜三縄間が開通し、高知から四国山地を越えて香川の多度津方面までが鉄道でつながった。", "source_url": "https://kotobank.jp/word/土讃線", "source_title": "コトバンク「土讃線」（改訂新版世界大百科事典・ブリタニカ国際大百科事典）"}, {"pref": "高知", "kind": "災い", "era": "昭和", "year": 1945, "title": "高知空襲", "text": "7月4日未明、B29の編隊が潮江地区や市街の中心部に焼夷弾を大量に落とし、多数の死傷者と罹災者を出した。", "source_url": "https://www.soumu.go.jp/main_sosiki/daijinkanbou/sensai/situation/state/shikoku_05.html", "source_title": "総務省「高知市における戦災の状況（高知県）」"}, {"pref": "青森", "kind": "災い", "era": "平安", "year": 915, "title": "十和田火山の噴火", "text": "915年、十和田の中湖で噴火が起き、湖の周囲に火砕流が流れ下った。泥流は米代川沿いに日本海まで達した。", "source_url": "https://kotobank.jp/word/十和田火山", "source_title": "最新 地学事典「十和田火山」（コトバンク）"}, {"pref": "青森", "kind": "恵み", "era": "中世", "year": 1312, "title": "安藤氏の十三湊", "text": "正和年間ごろ安藤氏が福島城を築き、潟全体を港とした。蝦夷地と日本海航路を結ぶ要港で、夷船・京船が集まり市をなしたという。", "source_url": "https://kotobank.jp/word/十三湊", "source_title": "日本大百科全書（ニッポニカ）・世界大百科事典「十三湊」（コトバンク）"}, {"pref": "青森", "kind": "災い", "era": "江戸", "year": 1782, "title": "天明の飢饉", "text": "天明年間、長雨・低温・霜による冷害で凶作が続き、津軽藩や八戸藩で飢えと病による死者が相次いだ。", "source_url": "https://kotobank.jp/word/天明の飢饉", "source_title": "日本大百科全書（ニッポニカ）・山川日本史小辞典「天明の飢饉」（コトバンク）"}, {"pref": "青森", "kind": "道がひらく", "era": "明治", "year": 1891, "title": "青森に鉄道が通じる", "text": "1891年、東北本線が青森まで開通した。1905年には奥羽本線も開通し、青森は二本の鉄道で各地と結ばれた。", "source_url": "https://kotobank.jp/word/青森市", "source_title": "ブリタニカ国際大百科事典 小項目事典「青森〔市〕」（コトバンク）"}, {"pref": "青森", "kind": "災い", "era": "明治", "year": 1902, "title": "八甲田山雪中行軍の遭難", "text": "1902年1月、ロシア軍の八戸付近上陸を想定した雪中行軍で、青森隊が八甲田山中で遭難した。", "source_url": "https://kotobank.jp/word/八甲田山雪中行軍", "source_title": "共同通信ニュース用語解説「八甲田山雪中行軍」（コトバンク）"}, {"pref": "青森", "kind": "道がひらく", "era": "明治", "year": 1908, "title": "青函連絡船の就航", "text": "1908年3月、国有鉄道が青森と函館を結ぶ連絡船の運航を始めた。前年に日本郵船から航路を買い取っていた。", "source_url": "https://kotobank.jp/word/青函連絡船", "source_title": "日本大百科全書（ニッポニカ）・百科事典マイペディア「青函連絡船」（コトバンク）"}, {"pref": "青森", "kind": "道がひらく", "era": "大正", "year": 1925, "title": "青函連絡船で貨車を運ぶ", "text": "1925年、青函連絡船に甲板へレールを敷いた船が入り、貨車をそのまま船に載せて青森と函館の間を運べるようになった。", "source_url": "https://kotobank.jp/word/青函連絡船", "source_title": "日本大百科全書（ニッポニカ）「青函連絡船」（コトバンク）"}, {"pref": "青森", "kind": "災い", "era": "昭和", "year": 1945, "title": "青森市街の戦災", "text": "第二次世界大戦の末期、1945年に青森市は戦災を受け、市街地を焼失した。", "source_url": "https://kotobank.jp/word/青森市", "source_title": "ブリタニカ国際大百科事典 小項目事典「青森〔市〕」（コトバンク）"}, {"pref": "栃木", "kind": "災い", "era": "平安", "year": 940, "title": "下野の秀郷、将門を討つ", "text": "940年2月、下野の押領使だった藤原秀郷は平貞盛らと下総へ攻め入り、平将門を倒した。この手柄で従四位下・下野守の位と官を得た。", "source_url": "https://kotobank.jp/word/藤原秀郷", "source_title": "世界大百科事典・日本大百科全書（ニッポニカ）「藤原秀郷」（コトバンク）"}, {"pref": "栃木", "kind": "行事", "era": "江戸", "year": 1617, "title": "日光東照宮の造営", "text": "1617年、家康の遺言により日光に社殿が整い東照宮が始まった。1636年には家光の命による大造替が行われた。", "source_url": "https://kotobank.jp/word/日光東照宮", "source_title": "山川日本史小辞典・改訂新版 世界大百科事典・日本大百科全書「日光東照宮」（コトバンク）"}, {"pref": "栃木", "kind": "道がひらく", "era": "江戸", "year": 1645, "title": "日光例幣使の派遣", "text": "1645年に東照宮が宮号を受けて以後、朝廷の例幣使が毎年日光へ遣わされ幕末まで続いた。往路は中山道と例幣使街道を通った。", "source_url": "https://kotobank.jp/word/日光東照宮", "source_title": "日本大百科全書（ニッポニカ）「日光東照宮」（コトバンク）"}, {"pref": "栃木", "kind": "道がひらく", "era": "明治", "year": 1884, "title": "県庁移転と鉄道開通", "text": "1884年に県庁が栃木から宇都宮へ移り、翌1885年には東北本線が宇都宮まで開通した。", "source_url": "https://kotobank.jp/word/宇都宮市", "source_title": "ブリタニカ国際大百科事典 小項目事典「宇都宮〔市〕」（コトバンク）"}, {"pref": "栃木", "kind": "災い", "era": "明治", "year": 1890, "title": "足尾鉱毒の広がり", "text": "1890年8月の渡良瀬川の大洪水で足尾銅山の鉱毒被害が深刻化した。流域の村々は採掘停止を訴え、1901年には田中正造が直訴を試みた。", "source_url": "https://kotobank.jp/word/足尾鉱毒事件", "source_title": "改訂新版 世界大百科事典「足尾鉱毒事件」（コトバンク）"}, {"pref": "栃木", "kind": "災い", "era": "大正", "year": 1917, "title": "谷中村残留民の立ち退き", "text": "鉱毒対策の遊水池にするため廃村とされた谷中村で、1907年の家屋破壊後も残った住民が、1917年に旧村を立ち退いた。", "source_url": "https://kotobank.jp/word/足尾鉱毒事件", "source_title": "改訂新版 世界大百科事典・山川日本史小辞典「足尾鉱毒事件」（コトバンク）"}, {"pref": "埼玉", "kind": "災い", "era": "中世", "year": 1590, "title": "忍城の水攻め", "text": "1590年、石田三成が忍城を囲み、守りの固さから城を囲む堤を築いて水攻めにした。城は落ちず、小田原落城の後に開城した。", "source_url": "https://kotobank.jp/word/忍城", "source_title": "日本の城がわかる事典「忍城」（コトバンク）"}, {"pref": "埼玉", "kind": "恵み", "era": "江戸", "year": 1727, "title": "見沼代用水の開削", "text": "見沼溜井を干拓して新田とし、代わりに利根川から水を引く見沼代用水を井沢弥惣兵衛が開いた。1728年に完成した。", "source_url": "https://kotobank.jp/word/見沼代用水", "source_title": "日本大百科全書（ニッポニカ）・山川日本史小辞典「見沼代用水」（コトバンク）"}, {"pref": "埼玉", "kind": "恵み", "era": "大正", "year": 1923, "title": "秩父セメントの創業", "text": "1923年、諸井恒平が秩父セメントを創業した。大正末に秩父に工場が開かれ、武甲山の石灰岩を原料にセメントをつくった。", "source_url": "https://kotobank.jp/word/秩父セメント", "source_title": "ブリタニカ国際大百科事典 小項目事典・世界大百科事典（旧版）「秩父セメント」（コトバンク）"}, {"pref": "埼玉", "kind": "災い", "era": "大正", "year": 1923, "title": "関東大震災", "text": "1923年9月1日の関東大震災の被害は、東京・神奈川などとともに埼玉県のほぼ全域に及んだ。", "source_url": "https://kotobank.jp/word/関東大震災", "source_title": "改訂新版 世界大百科事典「関東大震災」（コトバンク）"}, {"pref": "埼玉", "kind": "災い", "era": "昭和", "year": 1945, "title": "熊谷空襲", "text": "戦争が終わる前の晩、1945年8月14日の夜ふけに熊谷が空襲を受けた。市街地のおよそ3分の2がひと晩で焼け、266人が亡くなった。", "source_url": "https://www.city.kumagaya.lg.jp/shicho/kaiken/R5/7teirei.files/5tourou.pdf", "source_title": "熊谷市 記者クラブ取材情報「星川とうろう流し」（令和5年7月28日）"}, {"pref": "滋賀", "kind": "災い", "era": "中世", "year": 1428, "title": "正長の土一揆", "text": "1428年8月、近江坂本の馬借の蜂起に始まり、徳政を求める一揆が京都・奈良など畿内一帯に広がった。", "source_url": "https://kotobank.jp/word/正長の土一揆", "source_title": "日本大百科全書（ニッポニカ）・旺文社日本史事典「正長の土一揆」（コトバンク）"}, {"pref": "滋賀", "kind": "恵み", "era": "明治", "year": 1885, "title": "琵琶湖疏水の開削", "text": "大津の三保ヶ崎で琵琶湖の水を取り入れて京都へ送る疏水が1885年に着工し、1890年に完成した。舟運・発電・上水道・灌漑に使われた。", "source_url": "https://kotobank.jp/word/琵琶湖疏水", "source_title": "日本大百科全書（ニッポニカ）・日本歴史地名大系「琵琶湖疏水」（コトバンク）"}, {"pref": "滋賀", "kind": "恵み", "era": "昭和", "year": 1927, "title": "東洋レーヨン滋賀工場", "text": "1926年に創立された東洋レーヨンが、1927年に滋賀工場を設け、レーヨン糸の紡糸を始めた。", "source_url": "https://www.toray.co.jp/aboutus/history/index.html", "source_title": "東レ株式会社「東レの沿革」（創立〜1950年代）"}, {"pref": "山口", "kind": "災い", "era": "平安", "year": 940, "title": "純友勢が鋳銭司を焼く", "text": "藤原純友の乱のさなか、940年11月に純友の勢力が周防鋳銭司を焼いた。乱は瀬戸内各地に及び、941年に鎮められた。", "source_url": "https://kotobank.jp/word/藤原純友の乱", "source_title": "改訂新版 世界大百科事典「藤原純友の乱」（コトバンク）"}, {"pref": "山口", "kind": "災い", "era": "中世", "year": 1185, "title": "壇ノ浦の戦い", "text": "1185年3月24日、長門国赤間関の壇ノ浦で源平最後の海戦が行われ、平氏は滅亡し、安徳天皇は入水した。", "source_url": "https://kotobank.jp/word/壇ノ浦の戦い", "source_title": "精選版 日本国語大辞典・日本大百科全書（ニッポニカ）「壇ノ浦の戦い」（コトバンク）"}, {"pref": "山口", "kind": "災い", "era": "明治", "year": 1876, "title": "萩の乱", "text": "1876年10月、前原一誠らが萩の旧藩校明倫館に集まって挙兵したが、政府軍に鎮圧され、前原らは12月に処刑された。", "source_url": "https://kotobank.jp/word/萩の乱", "source_title": "日本大百科全書（ニッポニカ）・改訂新版 世界大百科事典「萩の乱」（コトバンク）"}, {"pref": "山口", "kind": "災い", "era": "大正", "year": 1918, "title": "宇部炭鉱の米騒動", "text": "1918年8月、米騒動が全国に広がるなか、宇部炭鉱でも暴動が起きた。軍隊が出動し、とくに激しい衝突となった。", "source_url": "https://kotobank.jp/word/米騒動", "source_title": "日本大百科全書（ニッポニカ）・改訂新版 世界大百科事典「米騒動」（コトバンク）"}, {"pref": "山口", "kind": "道がひらく", "era": "昭和", "year": 1942, "title": "関門トンネルの開通", "text": "1936年に着工した関門鉄道トンネルの下り線が1942年11月に完成した。上り線も1944年8月に完成した。", "source_url": "https://kotobank.jp/word/関門トンネル", "source_title": "改訂新版 世界大百科事典・山川日本史小辞典「関門トンネル」（コトバンク）"}, {"pref": "愛知", "kind": "災い", "era": "中世", "year": 1560, "title": "桶狭間の戦い", "text": "1560年5月19日、尾張桶狭間で織田信長が今川義元の大軍を破り、義元は戦死して今川軍は敗走した。", "source_url": "https://kotobank.jp/word/桶狭間の戦い", "source_title": "日本大百科全書（ニッポニカ）「桶狭間の戦い」（コトバンク）"}, {"pref": "愛知", "kind": "災い", "era": "明治", "year": 1891, "title": "濃尾地震", "text": "1891年10月28日、濃尾地震が起き、福井県南部から愛知県犬山の東方まで大断層が現れた。", "source_url": "https://kotobank.jp/word/濃尾地震", "source_title": "改訂新版 世界大百科事典・日本大百科全書（ニッポニカ）「濃尾地震」（コトバンク）"}, {"pref": "愛知", "kind": "災い", "era": "大正", "year": 1918, "title": "名古屋の米騒動", "text": "1918年8月10日夜、名古屋で大騒動が起き、鶴舞公園に集まった群衆が警官隊と衝突した。騒動は激化し、軍隊が出動して鎮圧した。", "source_url": "https://kotobank.jp/word/米騒動", "source_title": "日本大百科全書（ニッポニカ）「米騒動」（コトバンク）"}, {"pref": "愛知", "kind": "災い", "era": "昭和", "year": 1945, "title": "三河地震", "text": "1945年1月13日未明、三河湾を震源とする地震が起き、軍需産業地域の直下で多くの家屋が倒れた。戦時の情報統制で被害はあまり報道されなかった。", "source_url": "https://kotobank.jp/word/三河地震", "source_title": "デジタル大辞泉・共同通信ニュース用語解説「三河地震」（コトバンク）"}, {"pref": "愛知", "kind": "災い", "era": "昭和", "year": 1945, "title": "名古屋城の焼失", "text": "1945年の空襲で、名古屋城の天守群と本丸御殿などの大部分が焼失した。", "source_url": "https://kotobank.jp/word/名古屋城", "source_title": "日本の城がわかる事典・共同通信ニュース用語解説「名古屋城」（コトバンク）"}, {"pref": "愛媛", "kind": "災い", "era": "平安", "year": 939, "title": "藤原純友の乱", "text": "伊予に根を下ろした藤原純友が939年に兵を挙げ、伊予・讃岐をはじめ瀬戸内の各地を荒らした。大宰府攻めに敗れて伊予へ戻ったところを、941年6月に討ち取られた。", "source_url": "https://kotobank.jp/word/藤原純友の乱", "source_title": "改訂新版 世界大百科事典・山川日本史小辞典「藤原純友の乱」（コトバンク）"}, {"pref": "愛媛", "kind": "恵み", "era": "江戸", "year": 1691, "title": "別子銅山の開坑", "text": "1690年に見つかった別子銅山を、翌1691年に大坂の泉屋（住友）が開坑した。以後、住友家が経営を続けた。", "source_url": "https://kotobank.jp/word/別子銅山", "source_title": "日本大百科全書（ニッポニカ）・世界大百科事典「別子銅山」（コトバンク）"}, {"pref": "愛媛", "kind": "道がひらく", "era": "明治", "year": 1888, "title": "伊予鉄道の開業", "text": "1888年、松山で伊予鉄道が走り始めた。軽便鉄道のやり方を一般向けの鉄道に広めた最初の例とされる。", "source_url": "https://kotobank.jp/word/伊予鉄道", "source_title": "世界大百科事典（旧版）「軽便鉄道」（コトバンク「伊予鉄道」に収録）"}, {"pref": "愛媛", "kind": "災い", "era": "明治", "year": 1905, "title": "四阪島製錬所と煙害", "text": "1905年、住友が四阪島の製錬所を操業した。煙害は越智・周桑・新居・宇摩の東予四郡に及び、製錬量の制限や補償が行われた。", "source_url": "https://kotobank.jp/word/四阪島", "source_title": "日本大百科全書（ニッポニカ）「四阪島」（コトバンク）"}, {"pref": "愛媛", "kind": "災い", "era": "大正", "year": 1918, "title": "愛媛の米騒動", "text": "1918年、米価の高騰から全国に米騒動が広がり、和歌山県・香川県とともに愛媛県でも騒動が続発した。", "source_url": "https://kotobank.jp/word/米騒動", "source_title": "日本大百科全書（ニッポニカ）「米騒動」（コトバンク）"}, {"pref": "愛媛", "kind": "道がひらく", "era": "昭和", "year": 1927, "title": "予讃線が松山へ", "text": "1927年4月、予讃線が松山まで開業した。宇和島まで延びて全線が通じたのは1945年6月である。", "source_url": "https://kotobank.jp/word/予讃線", "source_title": "改訂新版 世界大百科事典・日本大百科全書（ニッポニカ）「予讃線」（コトバンク）"}, {"pref": "愛媛", "kind": "災い", "era": "昭和", "year": 1930, "title": "四阪島の煙害の解決", "text": "四阪島製錬所に1930年に脱硫装置、1939年に中和法の硫黄工場が完成し、長く続いた東予の大気汚染問題は解決した。", "source_url": "https://kotobank.jp/word/四阪島", "source_title": "日本大百科全書（ニッポニカ）・世界大百科事典「四阪島」（コトバンク）"}, {"pref": "徳島", "kind": "災い", "era": "中世", "year": 1185, "title": "義経の阿波上陸", "text": "1185年2月、源義経が摂津から船出して阿波の勝浦に上陸し、屋島の平氏を攻めた。", "source_url": "https://kotobank.jp/word/屋島の戦い", "source_title": "日本大百科全書（ニッポニカ）・ブリタニカ国際大百科事典「屋島の戦い」（コトバンク）"}, {"pref": "徳島", "kind": "災い", "era": "中世", "year": 1582, "title": "中富川の戦いと勝瑞落城", "text": "1582年、土佐の長宗我部元親が阿波に攻め入り、十河存保は中富川の戦いに敗れて讃岐へ逃れた。勝瑞城は落城し廃城となった。", "source_url": "https://kotobank.jp/word/勝瑞城", "source_title": "日本の城がわかる事典「勝瑞城」（コトバンク）"}, {"pref": "徳島", "kind": "恵み", "era": "江戸", "year": 1625, "title": "阿波藍の保護と専売", "text": "1625年に徳島藩が藍方役所を置き、1733年には藍方奉行所を新設して葉藍の専売を強めた。阿波藍は全国の市場をほぼ独占した。", "source_url": "https://kotobank.jp/word/阿波藍", "source_title": "日本大百科全書（ニッポニカ）「阿波藍」（コトバンク）"}, {"pref": "徳島", "kind": "災い", "era": "江戸", "year": 1756, "title": "藍玉税をめぐる一揆", "text": "1756年、藍玉に課された税の廃止を求める一揆が、名西郡を中心に計画された。", "source_url": "https://kotobank.jp/word/阿波国-28995", "source_title": "改訂新版 世界大百科事典「阿波国」（コトバンク）"}, {"pref": "徳島", "kind": "災い", "era": "江戸", "year": 1841, "title": "上郡騒動", "text": "1841年、三好郡を中心とするタバコ作の地帯で、上郡騒動と呼ばれる一揆が起こった。", "source_url": "https://kotobank.jp/word/阿波国-28995", "source_title": "改訂新版 世界大百科事典「阿波国」（コトバンク）"}, {"pref": "徳島", "kind": "道がひらく", "era": "明治", "year": 1899, "title": "徳島鉄道の開業", "text": "明治32〜33年、徳島から吉野川沿いに西へ向かう徳島鉄道が開業した。1907年には国有化された。", "source_url": "https://kotobank.jp/word/徳島線", "source_title": "日本大百科全書（ニッポニカ）・百科事典マイペディア「徳島線」（コトバンク）"}, {"pref": "徳島", "kind": "道がひらく", "era": "大正", "year": 1914, "title": "徳島線の全通", "text": "1914年、徳島から吉野川をさかのぼる徳島線が、川田から阿波池田までの区間の完成で全通した。", "source_url": "https://kotobank.jp/word/徳島線", "source_title": "精選版 日本国語大辞典・百科事典マイペディア「徳島線」（コトバンク）"}, {"pref": "徳島", "kind": "災い", "era": "昭和", "year": 1945, "title": "徳島大空襲", "text": "1945年7月4日、徳島大空襲で徳島の町なかはほとんどが焼けた。", "source_url": "https://www.city.tokushima.tokushima.jp/shisei/machi_keikaku/sougo-plan/shiminkaigi.files/02_shiryou2.pdf", "source_title": "徳島市 総合計画 市民会議資料2 ※検索結果の抜粋で確認"}, {"pref": "秋田", "kind": "災い", "era": "平安", "year": 878, "title": "元慶の乱", "text": "秋田城司の苛政に俘囚が立ち上がり、秋田城や郡院を焼いた。雄物川以北の独立を求め、派遣された国の兵を退けた。", "source_url": "https://kotobank.jp/word/元慶の乱", "source_title": "コトバンク「元慶の乱」（山川 日本史小辞典 改訂新版）"}, {"pref": "秋田", "kind": "災い", "era": "平安", "year": 1083, "title": "後三年合戦", "text": "出羽国仙北の清原氏の内紛に陸奥守源義家が加わり、戦いは五年に及んだ。金沢柵が落ち、清原氏は滅びた。", "source_url": "https://kotobank.jp/word/後三年の役", "source_title": "コトバンク「後三年の役」（世界大百科事典・山川 日本史小辞典・精選版 日本国語大辞典）"}, {"pref": "秋田", "kind": "恵み", "era": "江戸", "year": 1606, "title": "院内銀山の発見", "text": "慶長十一年に銀山が見つかり、秋田藩の直山となった。山あいに鉱山町が生まれ、天保期には大いに栄えた。", "source_url": "https://kotobank.jp/word/院内銀山", "source_title": "コトバンク「院内銀山」（日本大百科全書・世界大百科事典・山川 日本史小辞典）"}, {"pref": "秋田", "kind": "災い", "era": "江戸", "year": 1804, "title": "象潟地震", "text": "秋田・山形の県境で大地震が起き、松島と並ぶ景勝地だった象潟の入江が隆起して陸地や沼に変わった。", "source_url": "https://kotobank.jp/word/象潟地震", "source_title": "コトバンク「象潟地震」（最新 地学事典・デジタル大辞泉プラス）"}, {"pref": "秋田", "kind": "災い", "era": "明治", "year": 1868, "title": "戊辰戦争で秋田が戦場に", "text": "秋田藩は勤王に転じて奥羽越列藩同盟と対立し、東北で孤立した。同盟側の諸藩に攻め込まれ、領内の多くが戦場となった。", "source_url": "https://kotobank.jp/word/秋田藩", "source_title": "コトバンク「秋田藩」（世界大百科事典・百科事典マイペディア・日本大百科全書）"}, {"pref": "秋田", "kind": "災い", "era": "明治", "year": 1896, "title": "陸羽地震", "text": "秋田・岩手県境の真昼山地の直下で大地震が起き、秋田県東部を中心に家屋が倒れた。地表には千屋断層が現れた。", "source_url": "https://kotobank.jp/word/陸羽地震", "source_title": "コトバンク「陸羽地震」（最新 地学事典・デジタル大辞泉プラス）"}, {"pref": "秋田", "kind": "道がひらく", "era": "明治", "year": 1905, "title": "奥羽本線の全通", "text": "青森側と福島側から延びてきた線路が、明治三十八年九月の湯沢〜横手間の開通でつながり、奥羽本線が全通した。", "source_url": "https://kotobank.jp/word/奥羽本線", "source_title": "コトバンク「奥羽本線」（改訂新版 世界大百科事典・日本大百科全書）"}, {"pref": "秋田", "kind": "災い", "era": "大正", "year": 1914, "title": "秋田仙北地震（強首地震）", "text": "秋田県南部で地震が起き、仙北郡の被害がとくに重かった。強く揺れたのは横手盆地と雄物川沿いで、山崩れでできた池や、川の中に生まれた島もあった。", "source_url": "https://www.jma-net.go.jp/akita/data/saigai/akita_no_shizensaigai/detail/jisin-191403.pdf", "source_title": "秋田地方気象台「1914年（大正3年）3月15日の秋田県南部の地震（強首地震）による災害」"}, {"pref": "秋田", "kind": "災い", "era": "昭和", "year": 1939, "title": "男鹿地震", "text": "昭和十四年五月一日、男鹿半島で地震が起きた。半島の家々が倒れ、死者が出る災害となった。", "source_url": "https://kotobank.jp/word/男鹿地震", "source_title": "コトバンク「男鹿地震」（デジタル大辞泉プラス）"}, {"pref": "秋田", "kind": "災い", "era": "昭和", "year": 1945, "title": "土崎空襲", "text": "終戦前夜の八月十四日深夜から翌未明、日本石油秋田製油所を狙ってB29が土崎港に大量の爆弾を落とした。", "source_url": "https://kotobank.jp/word/土崎空襲", "source_title": "コトバンク「土崎空襲」（共同通信ニュース用語解説）"}, {"pref": "福島", "kind": "災い", "era": "中世", "year": 1189, "title": "阿津賀志山の戦い", "text": "源頼朝の奥州征伐で最大の激戦。奥州勢は山に城塞を築いて守ったが、背後の山から射かけられて崩れた。", "source_url": "https://kotobank.jp/word/阿津賀志山の戦", "source_title": "コトバンク「阿津賀志山の戦」（改訂新版 世界大百科事典）"}, {"pref": "福島", "kind": "恵み", "era": "江戸", "year": 1643, "title": "保科正之の会津入部", "text": "将軍家光の異母弟保科正之が会津に入った。漆・蝋を専売とし、社倉の制で米を蓄えて凶作の救済に備えた。", "source_url": "https://kotobank.jp/word/会津藩", "source_title": "コトバンク「会津藩」（日本大百科全書・山川 日本史小辞典・世界大百科事典）"}, {"pref": "福島", "kind": "災い", "era": "江戸", "year": 1787, "title": "天明の飢饉と会津の藩政改革", "text": "天明の大飢饉で会津藩は大きな打撃を受けた。飢饉の後、藩は農村の立て直しを目指す改革に乗り出した。", "source_url": "https://kotobank.jp/word/会津藩", "source_title": "コトバンク「会津藩」（日本大百科全書・山川 日本史小辞典）"}, {"pref": "福島", "kind": "恵み", "era": "江戸", "year": 1855, "title": "常磐の石炭の発見", "text": "安政二年、片寄平蔵が白水村弥勒沢で石炭の露頭を見つけた。のちに石狩・筑豊に次ぐ常磐炭田へ育っていく。", "source_url": "https://kotobank.jp/word/常磐炭田", "source_title": "コトバンク「常磐炭田」（日本歴史地名大系・世界大百科事典）"}, {"pref": "福島", "kind": "災い", "era": "明治", "year": 1868, "title": "会津戦争", "text": "母成峠を破った新政府軍が八月に若松城下へ攻め入った。籠城はおよそひと月続き、九月に会津藩は降伏・開城した。", "source_url": "https://kotobank.jp/word/会津戦争", "source_title": "コトバンク「会津戦争」（山川 日本史小辞典・日本大百科全書・改訂新版 世界大百科事典）"}, {"pref": "福島", "kind": "恵み", "era": "明治", "year": 1879, "title": "安積疏水の開削", "text": "猪苗代湖の水を安積原野へ引く国の事業。士族授産のため旧士族が入植し、明治十五年に通水した。", "source_url": "https://kotobank.jp/word/安積疏水", "source_title": "コトバンク「安積疏水」（日本歴史地名大系・山川 日本史小辞典・旺文社日本史事典）"}, {"pref": "福島", "kind": "災い", "era": "明治", "year": 1888, "title": "磐梯山の噴火", "text": "七月十五日、磐梯山が噴火して小磐梯が崩れ落ちた。岩屑と泥流が北麓の集落を埋め、檜原湖・小野川湖・秋元湖が生まれた。", "source_url": "https://kotobank.jp/word/磐梯山", "source_title": "コトバンク「磐梯山」（日本大百科全書・世界大百科事典・百科事典マイペディア）"}, {"pref": "福島", "kind": "恵み", "era": "大正", "year": 1914, "title": "常磐炭田の全盛", "text": "常磐線で京浜へ石炭を運べるようになった常磐炭田は、第一次大戦期に全盛を迎えた。飯場制度が入り、通勤する鉱夫も多かった。", "source_url": "https://kotobank.jp/word/常磐炭田", "source_title": "コトバンク「常磐炭田」（世界大百科事典・日本大百科全書）"}, {"pref": "茨城", "kind": "災い", "era": "平安", "year": 939, "title": "平将門の常陸国府襲撃", "text": "天慶二年、平将門が常陸国衙を襲って焼き払い、国守を捕らえた。これを機に将門は関東を短い間に制圧した。", "source_url": "https://kotobank.jp/word/平将門の乱", "source_title": "コトバンク「平将門の乱」（改訂新版 世界大百科事典・山川 日本史小辞典）"}, {"pref": "茨城", "kind": "災い", "era": "江戸", "year": 1864, "title": "天狗党の挙兵", "text": "元治元年三月、藤田小四郎らが筑波山で挙兵した。藩内の党争と重なり、常陸の農民も両派に分かれて巻き込まれた。", "source_url": "https://kotobank.jp/word/天狗党の乱", "source_title": "コトバンク「天狗党の乱」（日本大百科全書・世界大百科事典・山川 日本史小辞典）"}, {"pref": "茨城", "kind": "道がひらく", "era": "明治", "year": 1889, "title": "水戸鉄道の開業", "text": "明治二十二年、水戸鉄道が下野の小山から常陸の友部までの区間で開業した。", "source_url": "https://kotobank.jp/word/水戸線", "source_title": "コトバンク「水戸線」（日本大百科全書・ブリタニカ国際大百科事典）"}, {"pref": "茨城", "kind": "災い", "era": "昭和", "year": 1945, "title": "日立の戦災", "text": "昭和二十年六月から七月にかけ、日立は爆弾による空襲、沖合からの艦砲射撃、焼夷弾攻撃を受けた。", "source_url": "https://kyodonewsprwire.jp/release/201705242065", "source_title": "日立市（郷土博物館）発表「ギャラリー展『日立の戦災』の開催」（2017年・共同通信PRワイヤー掲載）"}, {"pref": "岐阜", "kind": "災い", "era": "平安", "year": 1181, "title": "墨俣川の戦い", "text": "養和元年三月、源行家らの軍と平氏の軍が美濃の墨俣川で向かい合った。平氏の先制の夜襲で源氏方は大敗した。", "source_url": "https://kotobank.jp/word/墨俣川の戦", "source_title": "コトバンク「墨俣川の戦」（改訂新版 世界大百科事典・百科事典マイペディア）"}, {"pref": "岐阜", "kind": "災い", "era": "中世", "year": 1586, "title": "天正地震と帰雲城の埋没", "text": "天正の大地震で帰雲山の山腹が大きく崩れ、内ヶ島氏の帰雲城と城下町がひと息に埋まった。", "source_url": "https://kotobank.jp/word/帰雲城", "source_title": "コトバンク「帰雲城」（日本の城がわかる事典）"}, {"pref": "岐阜", "kind": "災い", "era": "中世", "year": 1600, "title": "関ヶ原の戦い", "text": "慶長五年九月十五日、美濃の関ヶ原で徳川家康の東軍と石田三成の西軍がぶつかった。小早川秀秋の内応で西軍は崩れた。", "source_url": "https://kotobank.jp/word/関ヶ原の戦", "source_title": "コトバンク「関ヶ原の戦」（改訂新版 世界大百科事典・百科事典マイペディア）"}, {"pref": "岐阜", "kind": "災い", "era": "江戸", "year": 1754, "title": "郡上一揆（宝暦）", "text": "郡上藩の検見取りによる年貢増徴に百姓が反対した。幕府の裁きで藩主金森氏は領地を失い、老中まで処分された。", "source_url": "https://kotobank.jp/word/郡上一揆", "source_title": "コトバンク「郡上一揆」（世界大百科事典・山川 日本史小辞典）"}, {"pref": "岐阜", "kind": "災い", "era": "江戸", "year": 1771, "title": "大原騒動", "text": "飛騨郡代大原紹正の検地強行などに、飛騨の百姓が十八年にわたり断続的に一揆を起こした。のちに郡代は遠島となった。", "source_url": "https://kotobank.jp/word/大原騒動", "source_title": "コトバンク「大原騒動」（世界大百科事典（旧版）「飛驒国」「飛驒郡代」）"}, {"pref": "岐阜", "kind": "災い", "era": "明治", "year": 1891, "title": "濃尾地震", "text": "十月二十八日早朝、美濃・尾張を大地震が襲った。根尾谷断層が現れ、水鳥では地面に大きな段差ができた。", "source_url": "https://kotobank.jp/word/濃尾地震", "source_title": "コトバンク「濃尾地震」（日本大百科全書・世界大百科事典・最新 地学事典ほか）"}, {"pref": "岐阜", "kind": "道がひらく", "era": "昭和", "year": 1934, "title": "高山本線の全通", "text": "岐阜側と富山側から延びた線路が昭和九年十月につながり、高山本線となった。飛騨の山あいが鉄道で中京・北陸と結ばれた。", "source_url": "https://kotobank.jp/word/高山本線", "source_title": "コトバンク「高山本線」（改訂新版 世界大百科事典・精選版 日本国語大辞典）"}, {"pref": "岐阜", "kind": "災い", "era": "昭和", "year": 1945, "title": "岐阜空襲", "text": "昭和二十年七月九日夜、B29の編隊が岐阜市の中心部に焼夷弾を落とした。市街地の大部分が焼け、百貨店も炎上した。", "source_url": "https://www.soumu.go.jp/main_sosiki/daijinkanbou/sensai/situation/state/tokai_01.html", "source_title": "総務省「岐阜市における戦災の状況（岐阜県）」"}, {"pref": "広島", "kind": "行事", "era": "平安", "year": 1168, "title": "厳島神社の大修築", "text": "平家一門の崇敬を受け、仁安三年に神主佐伯景弘が厳島神社を大きく修築した。", "source_url": "https://kotobank.jp/word/厳島神社", "source_title": "コトバンク「厳島神社」（改訂新版 世界大百科事典）"}, {"pref": "広島", "kind": "恵み", "era": "平安", "year": 1168, "title": "尾道に大田荘の倉敷地", "text": "仁安三年、備後の大田荘の倉敷地が尾道に置かれた。荘園の年貢を船で運び出す港として、尾道の発展が始まった。", "source_url": "https://kotobank.jp/word/尾道", "source_title": "コトバンク「尾道」（世界大百科事典）"}, {"pref": "広島", "kind": "災い", "era": "中世", "year": 1555, "title": "厳島の戦い", "text": "弘治元年、毛利元就が厳島で陶晴賢を破った。毛利氏は広島湾頭を押さえ、中国地方の制覇へ向かった。", "source_url": "https://kotobank.jp/word/厳島の戦", "source_title": "コトバンク「厳島の戦」（改訂新版 世界大百科事典・山川 日本史小辞典・百科事典マイペディア）"}, {"pref": "広島", "kind": "恵み", "era": "江戸", "year": 1619, "title": "浅野氏の入封", "text": "福島正則の改易後、浅野長晟が紀伊から入った。沿岸の塩・牡蠣・海苔、山の鉄・紙が藩の名産となり、鉄や紙は専売とされた。", "source_url": "https://kotobank.jp/word/広島藩", "source_title": "コトバンク「広島藩」（日本大百科全書・改訂新版 世界大百科事典）"}, {"pref": "広島", "kind": "災い", "era": "江戸", "year": 1718, "title": "享保の全藩一揆", "text": "享保三年、広島藩領全体に及ぶ一揆が起きた。農村の締めつけを強めた正徳の新格は撤回された。", "source_url": "https://kotobank.jp/word/広島藩", "source_title": "コトバンク「広島藩」（改訂新版 世界大百科事典）"}, {"pref": "広島", "kind": "恵み", "era": "明治", "year": 1889, "title": "宇品港の築港", "text": "明治二十二年に宇品港が完成した。日清戦争からは軍港として使われ、兵や物資が行き交った。", "source_url": "https://kotobank.jp/word/宇品港", "source_title": "コトバンク「宇品港」（日本歴史地名大系）"}, {"pref": "広島", "kind": "災い", "era": "明治", "year": 1894, "title": "広島に大本営", "text": "日清戦争で大本営が東京から広島へ移り、天皇や政府の要人が滞在した。仮議事堂で帝国議会も開かれた。", "source_url": "https://www.city.hiroshima.lg.jp/tourism-culture/history/1003068/1027532/1035526/1035527.html", "source_title": "広島市 Web展示会「疫禍来襲!! 近代以降の伝染病と広島の歴史」日清戦争前後の伝染病対策"}, {"pref": "広島", "kind": "恵み", "era": "大正", "year": 1915, "title": "広島県物産陳列館の完成", "text": "チェコの建築家ヤン・レツルの設計で広島県物産陳列館が建った。県の産業振興と展示の場として使われた。", "source_url": "https://kotobank.jp/word/原爆ドーム", "source_title": "コトバンク「原爆ドーム」（事典 日本の地域遺産・共同通信ニュース用語解説）"}, {"pref": "広島", "kind": "災い", "era": "昭和", "year": 1945, "title": "原子爆弾の投下", "text": "昭和二十年八月六日、広島に世界で初めて原子爆弾が投下された。市街は壊滅し、産業奨励館も大破・全焼した。", "source_url": "https://kotobank.jp/word/原爆ドーム", "source_title": "コトバンク「原爆ドーム」（事典 日本の地域遺産・日本大百科全書）／「広島市」（ブリタニカ）"}, {"pref": "静岡", "kind": "災い", "era": "平安", "year": 1180, "title": "富士川の戦い", "text": "治承四年十月、富士川をはさんで平維盛の軍と源頼朝の軍が向き合い、平氏軍はほとんど戦わずに退いた。", "source_url": "https://kotobank.jp/word/富士川の戦", "source_title": "コトバンク「富士川の戦」（改訂新版 世界大百科事典・山川 日本史小辞典）"}, {"pref": "静岡", "kind": "災い", "era": "中世", "year": 1498, "title": "明応地震と今切", "text": "明応七年の大地震で浜名湖の岸が切れて海とつながった。今切の地名はこのとき生まれた。遠江では山が崩れ地が裂けた。", "source_url": "https://kotobank.jp/word/明応地震", "source_title": "コトバンク「明応地震」（改訂新版 世界大百科事典）"}, {"pref": "静岡", "kind": "災い", "era": "江戸", "year": 1707, "title": "宝永の噴火", "text": "宝永地震の四十九日後、富士山の南東山腹が噴火し、二週間ほど続いた。家が焼け、火山灰が田畑に積もった。", "source_url": "https://kotobank.jp/word/宝永噴火", "source_title": "コトバンク「宝永噴火」（共同通信ニュース用語解説）"}, {"pref": "静岡", "kind": "災い", "era": "江戸", "year": 1854, "title": "安政東海地震", "text": "安政元年十一月四日朝、遠州灘沖から駿河湾内にかけての海底で大地震が起きた。房総から土佐の沿岸を津波が襲った。", "source_url": "https://kotobank.jp/word/安政東海地震", "source_title": "コトバンク「安政東海地震」（世界大百科事典（旧版）・デジタル大辞泉プラス）"}, {"pref": "静岡", "kind": "恵み", "era": "明治", "year": 1869, "title": "牧之原の茶園開墾", "text": "職を失った徳川家の旧幕臣が刀を鍬に持ちかえ、明治二年に牧之原の開拓を始めた。川越制度の廃止で職を失った人足も加わった。", "source_url": "https://www.maff.go.jp/kanto/nouson/sekkei/kokuei/nishikan/makinohara/rekishi.html", "source_title": "農林水産省関東農政局「牧之原の歴史」"}, {"pref": "静岡", "kind": "道がひらく", "era": "大正", "year": 1918, "title": "丹那トンネルの着工", "text": "大正七年、熱海と函南を結ぶ丹那トンネルの工事が始まった。高圧の湧水や断層に悩み、完成まで十六年かかった。", "source_url": "https://kotobank.jp/word/丹那トンネル", "source_title": "コトバンク「丹那トンネル」（改訂新版 世界大百科事典・日本大百科全書・山川 日本史小辞典）"}, {"pref": "静岡", "kind": "災い", "era": "昭和", "year": 1930, "title": "北伊豆地震", "text": "昭和五年十一月二十六日未明、伊豆半島北部で大地震が起きた。丹那断層が動き、工事中の丹那トンネル内にもずれが生じた。", "source_url": "https://kotobank.jp/word/北伊豆地震", "source_title": "コトバンク「北伊豆地震」（デジタル大辞泉・最新 地学事典・日本大百科全書）"}, {"pref": "静岡", "kind": "災い", "era": "昭和", "year": 1944, "title": "浜松の空襲と艦砲射撃", "text": "航空隊の基地と軍需工場の町だった浜松は、艦砲射撃を含む攻撃を受け、市街地の大部分が焼けた。", "source_url": "https://www.soumu.go.jp/main_sosiki/daijinkanbou/sensai/situation/state/tokai_03.html", "source_title": "総務省「浜松市における戦災の状況（静岡県）」／浜松市「復興記念館」"}, {"pref": "香川", "kind": "災い", "era": "中世", "year": 1185, "title": "屋島の戦い", "text": "文治元年二月、屋島に拠った平氏を源義経が背後から奇襲した。平氏は敗れて海へ逃れ、長門へ向かった。", "source_url": "https://kotobank.jp/word/屋島の戦", "source_title": "コトバンク「屋島の戦」（改訂新版 世界大百科事典・山川 日本史小辞典・精選版 日本国語大辞典）"}, {"pref": "香川", "kind": "恵み", "era": "江戸", "year": 1830, "title": "讃岐の白砂糖", "text": "十八世紀末に向山周慶らが白砂糖づくりを始め、天保の初めには高松藩産の砂糖が大坂の市場に出回るようになった。", "source_url": "https://kotobank.jp/word/讃岐三白", "source_title": "コトバンク「讃岐三白」（世界大百科事典（旧版）「讃岐国」「讃岐平野」）"}, {"pref": "香川", "kind": "道がひらく", "era": "明治", "year": 1889, "title": "讃岐鉄道の開業", "text": "明治二十二年五月、讃岐鉄道が丸亀〜多度津〜琴平間で開業した。のちに高松まで延びた。", "source_url": "https://kotobank.jp/word/讃岐鉄道", "source_title": "コトバンク「讃岐鉄道」（世界大百科事典（旧版）「予讃線」）"}, {"pref": "香川", "kind": "道がひらく", "era": "明治", "year": 1910, "title": "宇高連絡船の就航", "text": "明治四十三年、高松と岡山県の宇野を結ぶ国鉄の連絡船が開業した。", "source_url": "https://kotobank.jp/word/宇高連絡船", "source_title": "コトバンク「宇高連絡船」（精選版 日本国語大辞典・デジタル大辞泉）"}, {"pref": "香川", "kind": "災い", "era": "昭和", "year": 1945, "title": "高松空襲", "text": "昭和二十年七月四日未明、高松は米軍B29の空襲を受け、旧市街が焦土となった。", "source_url": "https://www.city.takamatsu.kagawa.jp/kurashi/shinotorikumi/jinken/keihatsu/heiwa/dayori.files/dayori96.pdf", "source_title": "高松市平和記念館「平和記念だより」96号（2025年7月）"}, {"pref": "鹿児島", "kind": "災い", "era": "平安", "year": 874, "title": "開聞岳の噴火", "text": "貞観十六年、薩摩の開聞岳が大きく噴火した。十一年後の仁和元年にも大噴火の記録がある。", "source_url": "https://kotobank.jp/word/開聞岳", "source_title": "コトバンク「開聞岳」（精選版 日本国語大辞典・日本大百科全書・改訂新版 世界大百科事典）"}, {"pref": "鹿児島", "kind": "災い", "era": "江戸", "year": 1779, "title": "桜島の安永噴火", "text": "安永八年、桜島の山腹が噴火して溶岩が山麓の集落を襲った。北東の海には新しい島々が現れ、のちに人が住みついた。", "source_url": "https://kotobank.jp/word/桜島", "source_title": "コトバンク「桜島」（日本歴史地名大系・日本大百科全書・世界大百科事典）"}, {"pref": "鹿児島", "kind": "恵み", "era": "江戸", "year": 1852, "title": "集成館事業", "text": "藩主島津斉彬が磯の邸内に洋式工場を集め、反射炉や溶鉱炉を築いた。大砲のほかガラス・陶器・紙なども作った。", "source_url": "https://kotobank.jp/word/集成館", "source_title": "コトバンク「集成館」（ブリタニカ国際大百科事典・山川 日本史小辞典・旺文社日本史事典）"}, {"pref": "鹿児島", "kind": "災い", "era": "江戸", "year": 1863, "title": "薩英戦争", "text": "生麦事件の賠償交渉が決裂し、文久三年七月、英国艦隊が鹿児島を砲撃した。城下は火の海となり、集成館も焼けた。", "source_url": "https://kotobank.jp/word/薩英戦争", "source_title": "コトバンク「薩英戦争」（世界大百科事典・日本大百科全書・山川 日本史小辞典）"}, {"pref": "鹿児島", "kind": "災い", "era": "明治", "year": 1877, "title": "西南戦争の終わり", "text": "明治十年九月、鹿児島に戻った西郷軍は城山にこもり、政府軍の総攻撃を受けた。西郷隆盛は岩崎谷で自刃した。", "source_url": "https://kotobank.jp/word/城山", "source_title": "コトバンク「城山」（日本歴史地名大系・日本大百科全書・精選版 日本国語大辞典）"}, {"pref": "鹿児島", "kind": "災い", "era": "大正", "year": 1914, "title": "桜島の大正噴火", "text": "大正三年一月十二日から桜島が大噴火した。流れ出た溶岩が瀬戸の海峡を埋め、桜島は大隅半島と陸続きになった。", "source_url": "https://kotobank.jp/word/桜島", "source_title": "コトバンク「桜島」（日本大百科全書・ブリタニカ国際大百科事典・日本歴史地名大系）"}, {"pref": "鹿児島", "kind": "災い", "era": "昭和", "year": 1945, "title": "鹿児島空襲", "text": "昭和二十年三月十八日から八月六日まで、鹿児島市は空襲を受けた。最も被害が大きかったのは六月十七日だった。", "source_url": "https://www.city.kagoshima.lg.jp/soumu/soumu/soumu/kurashi/hewa/sensai/jokyo-1.html", "source_title": "鹿児島市「空襲等の概況」"}, {"pref": "岩手", "kind": "恵み", "era": "平安", "year": 1124, "title": "中尊寺金色堂の建立", "text": "藤原清衡が中尊寺に阿弥陀堂の金色堂を建てた。漆塗りの上に金箔を押した堂で、清衡・基衡・秀衡の三代がここに葬られた。", "source_url": "https://kotobank.jp/word/中尊寺金色堂", "source_title": "コトバンク「中尊寺金色堂」（山川日本史小辞典・旺文社日本史事典）"}, {"pref": "岩手", "kind": "災い", "era": "中世", "year": 1189, "title": "奥州合戦、平泉の陥落", "text": "源頼朝の軍が阿津賀志山で奥州軍の主力を破って平泉へ進んだ。藤原泰衡は館に火を放って北へ逃れたが郎従に討たれ、奥州藤原氏は滅んだ。", "source_url": "https://kotobank.jp/word/奥州合戦", "source_title": "コトバンク「奥州合戦」（山川日本史小辞典）"}, {"pref": "岩手", "kind": "災い", "era": "中世", "year": 1591, "title": "九戸政実の乱", "text": "南部信直の一族九戸政実が奥羽仕置に反発して信直に背いた。秀吉が送った奥羽諸軍の大軍に囲まれて降伏し、城兵は皆殺しにされた。", "source_url": "https://kotobank.jp/word/九戸政実の乱", "source_title": "コトバンク「九戸政実の乱」（改訂新版世界大百科事典）"}, {"pref": "岩手", "kind": "災い", "era": "江戸", "year": 1783, "title": "天明の飢饉", "text": "八戸のあたりでは夏にやませが吹きつけ、稲が実らないまま枯れた。盛岡藩・八戸藩では飢えや病で命を落とす人が続いた。", "source_url": "https://kotobank.jp/word/天明の飢饉", "source_title": "コトバンク「天明の飢饉」（日本大百科全書・山川日本史小辞典）"}, {"pref": "岩手", "kind": "災い", "era": "江戸", "year": 1847, "title": "三閉伊一揆", "text": "盛岡藩沿岸の農民・漁民が専売制の強化や御用金に反対して強訴した。約束が守られず再び起こした1853年の一揆では、多くの要求を認めさせた。", "source_url": "https://kotobank.jp/word/三閉伊一揆", "source_title": "コトバンク「三閉伊一揆」（改訂新版世界大百科事典・百科事典マイペディア・山川日本史小辞典）"}, {"pref": "岩手", "kind": "恵み", "era": "江戸", "year": 1857, "title": "大橋に洋式高炉", "text": "大島高任が釜石の大橋に洋式高炉を築き、近代製鉄法による精錬に成功した。日本で最初の洋式高炉とされる。", "source_url": "https://kotobank.jp/word/釜石製鉄所", "source_title": "コトバンク「釜石製鉄所」（日本大百科全書・旺文社日本史事典・世界大百科事典）"}, {"pref": "岩手", "kind": "恵み", "era": "明治", "year": 1887, "title": "釜石の製鉄、民営で再出発", "text": "国が営んだ釜石の製鉄所はうまくいかなかったが、田中長兵衛がこれを譲り受け、1887年に釜石鉱山田中製鉄所の名で民間の手で立て直した。", "source_url": "https://kotobank.jp/word/釜石製鉄所", "source_title": "コトバンク「釜石製鉄所」（日本大百科全書）"}, {"pref": "岩手", "kind": "恵み", "era": "明治", "year": 1891, "title": "小岩井農場の開設", "text": "井上勝・小野義真・岩崎弥之助が岩手山南麓の原野を開き、大農場式の牧場を始めた。農場の名は三人の姓の頭文字から。", "source_url": "https://kotobank.jp/word/小岩井農場", "source_title": "コトバンク「小岩井農場」（デジタル大辞泉・日本歴史地名大系・山川日本史小辞典ほか）"}, {"pref": "岩手", "kind": "災い", "era": "明治", "year": 1896, "title": "明治三陸地震津波", "text": "三陸沖で起きた地震の大津波が沿岸を襲い、綾里村をはじめ各地で家屋が流され、多くの死者・行方不明者が出た。", "source_url": "https://kotobank.jp/word/明治三陸地震津波", "source_title": "コトバンク「明治三陸地震津波」（ブリタニカ国際大百科事典・デジタル大辞泉プラス）"}, {"pref": "岩手", "kind": "道がひらく", "era": "大正", "year": 1913, "title": "岩手軽便鉄道の開業", "text": "花巻から仙人峠方面へ向かう軽便鉄道が開業した。のちに国有化されて釜石線となる。", "source_url": "https://kotobank.jp/word/釜石線", "source_title": "コトバンク「釜石線」（日本大百科全書・ブリタニカ国際大百科事典）"}, {"pref": "岩手", "kind": "災い", "era": "昭和", "year": 1933, "title": "昭和三陸地震津波", "text": "三陸はるか沖の地震で、津波が岩手県を中心とする沿岸を襲った。田老村などで死者・行方不明者が出た。", "source_url": "https://kotobank.jp/word/昭和三陸地震津波", "source_title": "コトバンク「昭和三陸地震津波」（ブリタニカ国際大百科事典）"}, {"pref": "岩手", "kind": "道がひらく", "era": "昭和", "year": 1936, "title": "軽便鉄道が国有の釜石線に", "text": "岩手軽便鉄道の花巻〜仙人峠間が国有化され、釜石線となった。", "source_url": "https://kotobank.jp/word/釜石線", "source_title": "コトバンク「釜石線」（日本大百科全書・百科事典マイペディア）"}, {"pref": "福井", "kind": "災い", "era": "中世", "year": 1573, "title": "一乗谷の朝倉氏滅ぶ", "text": "京の戦乱を逃れた公家や文化人が訪れ「越南の都」と呼ばれた一乗谷は、朝倉義景が織田信長に敗れて百年余りの城下の歴史を閉じた。", "source_url": "https://kotobank.jp/word/一乗谷", "source_title": "コトバンク「一乗谷」（日本歴史地名大系・改訂新版世界大百科事典）"}, {"pref": "福井", "kind": "恵み", "era": "明治", "year": 1899, "title": "敦賀が開港場に", "text": "敦賀が開港場に指定され、外国との貿易の港となった。", "source_url": "https://kotobank.jp/word/敦賀市", "source_title": "コトバンク「敦賀市」（ブリタニカ国際大百科事典）"}, {"pref": "福井", "kind": "道がひらく", "era": "明治", "year": 1902, "title": "ウラジオストク航路の開設", "text": "敦賀港とウラジオストク（ロシア）を結ぶ定期の航路ができた。", "source_url": "https://kotobank.jp/word/敦賀市", "source_title": "コトバンク「敦賀市」（ブリタニカ国際大百科事典）"}, {"pref": "福井", "kind": "道がひらく", "era": "昭和", "year": 1940, "title": "「命のビザ」のユダヤ難民が上陸", "text": "迫害を逃れ、杉原千畝が発給したビザを携えたユダヤ難民が、ウラジオストクを経て敦賀港に上陸した。市民は温かく迎えたと伝わる。", "source_url": "https://tsuruga-museum.jp/modules/permanentexhibition/index.php?action=PageView&page_id=5", "source_title": "人道の港 敦賀ムゼウム 常設展示「ユダヤ難民」"}, {"pref": "福井", "kind": "災い", "era": "昭和", "year": 1945, "title": "福井空襲", "text": "空襲によって福井の市街地は壊滅状態となった。", "source_url": "https://kotobank.jp/word/福井市", "source_title": "コトバンク「福井市」（ブリタニカ国際大百科事典）"}, {"pref": "島根", "kind": "災い", "era": "昭和", "year": 1934, "title": "斐伊川の台風洪水", "text": "九月の台風で斐伊川が出水し、流域に洪水の被害が出た。斐伊川の著名な洪水の一つに数えられる。", "source_url": "https://www.mlit.go.jp/river/basic_info/jigyo_keikaku/gaiyou/seibi/pdf/hii-4-4.pdf", "source_title": "国土交通省 斐伊川水系 河川整備資料（hii-4-4.pdf）"}, {"pref": "島根", "kind": "災い", "era": "昭和", "year": 1943, "title": "昭和十八年の斐伊川洪水", "text": "九月の台風で斐伊川が出水し、堤防が切れ、田畑や家屋が水につかった。斐伊川の著名な洪水の一つに数えられる。", "source_url": "https://www.mlit.go.jp/river/basic_info/jigyo_keikaku/gaiyou/seibi/pdf/hii-4-4.pdf", "source_title": "国土交通省 斐伊川水系 河川整備資料（hii-4-4.pdf）"}, {"pref": "長野", "kind": "災い", "era": "中世", "year": 1553, "title": "川中島の戦い", "text": "武田信玄に追われた村上義清らが上杉謙信を頼り、川中島で両軍が幾度も対陣した。1561年の八幡原での衝突は激戦となった。", "source_url": "https://kotobank.jp/word/川中島の戦", "source_title": "コトバンク「川中島の戦」（改訂新版世界大百科事典・山川日本史小辞典・百科事典マイペディア）"}, {"pref": "長野", "kind": "災い", "era": "江戸", "year": 1847, "title": "善光寺地震", "text": "善光寺の御開帳で参詣者があふれる門前を大地震が襲った。山崩れが犀川をせき止めて湖ができ、のちに決壊して洪水となった。", "source_url": "https://kotobank.jp/word/善光寺地震", "source_title": "コトバンク「善光寺地震」（デジタル大辞泉・日本大百科全書・改訂新版世界大百科事典ほか）"}, {"pref": "長野", "kind": "恵み", "era": "明治", "year": 1873, "title": "岡谷に洋式の製糸工場", "text": "養蚕を主とする農村だった岡谷に洋式の製糸工場が入った。以後、製糸業の町として急速に発展した。", "source_url": "https://kotobank.jp/word/岡谷市", "source_title": "コトバンク「岡谷市」（ブリタニカ国際大百科事典）"}, {"pref": "長野", "kind": "道がひらく", "era": "明治", "year": 1893, "title": "碓氷峠を越える鉄道が全通", "text": "碓氷峠の急勾配をアプト式で越え、高崎から軽井沢・長野を経て直江津までの鉄道が全通した。", "source_url": "https://kotobank.jp/word/信越本線", "source_title": "コトバンク「信越本線」（精選版日本国語大辞典・ブリタニカ・改訂新版世界大百科事典）"}, {"pref": "長野", "kind": "災い", "era": "昭和", "year": 1932, "title": "満蒙開拓団の送出", "text": "国策として満州へ開拓移民が送り出され、長野県は都道府県別で最も多くの人を送り出した。敗戦時には多くの犠牲者が出た。", "source_url": "https://kotobank.jp/word/満蒙開拓団", "source_title": "コトバンク「満蒙開拓団」（共同通信ニュース用語解説・デジタル大辞泉・山川日本史小辞典）"}, {"pref": "岡山", "kind": "災い", "era": "平安", "year": 1184, "title": "藤戸の合戦", "text": "源範頼の軍の佐々木盛綱が、浦の男に教わった浅瀬を馬で渡って児島の平家方を攻めた。全軍が続き、平家方は屋島へ退いた。", "source_url": "https://kotobank.jp/word/藤戸", "source_title": "コトバンク「藤戸」（日本大百科全書・改訂新版世界大百科事典）"}, {"pref": "岡山", "kind": "災い", "era": "中世", "year": 1582, "title": "備中高松城の水攻め", "text": "羽柴秀吉が足守川をせき止める堤を築き、城を水没させた。本能寺の変の報を受けた秀吉は、城主清水宗治の切腹を条件に毛利方と講和した。", "source_url": "https://kotobank.jp/word/高松城水攻め", "source_title": "コトバンク「高松城水攻め」（日本大百科全書）"}, {"pref": "岡山", "kind": "災い", "era": "江戸", "year": 1856, "title": "渋染一揆", "text": "倹約令が被差別部落の人々の衣類を渋染・藍染に限るなどの差別条項を定めたのに対し、領内の村々が結束して吉井川の河原に集まり強訴した。", "source_url": "https://kotobank.jp/word/渋染一揆", "source_title": "コトバンク「渋染一揆」（改訂新版世界大百科事典・日本大百科全書・山川日本史小辞典・マイペディア）"}, {"pref": "岡山", "kind": "恵み", "era": "明治", "year": 1888, "title": "倉敷紡績の創設", "text": "幕府の代官所が置かれ米と綿花の集散地だった倉敷に、倉敷紡績が創られた。これが倉敷の工業化の第一歩となった。", "source_url": "https://kotobank.jp/word/倉敷市", "source_title": "コトバンク「倉敷市」（ブリタニカ国際大百科事典）"}, {"pref": "岡山", "kind": "道がひらく", "era": "明治", "year": 1891, "title": "山陽鉄道が岡山へ", "text": "山陽本線が岡山まで開通し、以来岡山は山陽地方の交通と経済の中心となった。", "source_url": "https://kotobank.jp/word/岡山市", "source_title": "コトバンク「岡山市」（ブリタニカ国際大百科事典）"}, {"pref": "岡山", "kind": "恵み", "era": "大正", "year": 1921, "title": "倉敷労働科学研究所の創立", "text": "倉敷紡績の大原孫三郎が、医学や心理学を軸に働く人の労働を研究する倉敷労働科学研究所を倉敷に創った。", "source_url": "https://kotobank.jp/word/大原孫三郎", "source_title": "コトバンク「大原孫三郎」（改訂新版世界大百科事典）・「労働科学研究所」（世界大百科事典）"}, {"pref": "岡山", "kind": "災い", "era": "昭和", "year": 1934, "title": "室戸台風の水害", "text": "九月に上陸した室戸台風で、台風の北西側にあたった岡山県では水害が多く出た。", "source_url": "https://kotobank.jp/word/室戸台風", "source_title": "コトバンク「室戸台風」（日本大百科全書）"}, {"pref": "岡山", "kind": "災い", "era": "昭和", "year": 1945, "title": "岡山空襲", "text": "六月二十九日未明の空襲で、岡山の中心市街地の大部分が焼け、多くの市民が亡くなった。", "source_url": "https://www.soumu.go.jp/main_sosiki/daijinkanbou/sensai/situation/state/chugoku_02.html", "source_title": "総務省「岡山市における戦災の状況（岡山県）」"}, {"pref": "神奈川", "kind": "災い", "era": "平安", "year": 1180, "title": "石橋山の戦い", "text": "挙兵した源頼朝の軍が、相模の石橋山で平氏方の大庭景親らに大敗した。頼朝は山中に逃れ、真鶴から海路で安房へ渡って再起した。", "source_url": "https://kotobank.jp/word/石橋山の戦", "source_title": "コトバンク「石橋山の戦」（改訂新版世界大百科事典・山川日本史小辞典・マイペディア）"}, {"pref": "神奈川", "kind": "災い", "era": "中世", "year": 1333, "title": "鎌倉幕府の滅亡", "text": "新田義貞らが鎌倉を攻め、北条高時以下の北条一門と御内人は東勝寺で自刃した。鎌倉幕府はここに滅んだ。", "source_url": "https://kotobank.jp/word/元弘の乱", "source_title": "コトバンク「元弘の乱」（山川日本史小辞典・マイペディア・改訂新版世界大百科事典）"}, {"pref": "神奈川", "kind": "災い", "era": "中世", "year": 1590, "title": "小田原攻め", "text": "豊臣秀吉の大軍が小田原を囲み、石垣山に一夜城を築いて長期戦となった。支城が次々に落ち、北条氏直は降伏した。", "source_url": "https://kotobank.jp/word/小田原攻め", "source_title": "コトバンク「小田原攻め」（山川日本史小辞典）"}, {"pref": "神奈川", "kind": "災い", "era": "江戸", "year": 1707, "title": "富士山の降灰と酒匂川の決壊", "text": "富士山宝永山の噴火で降った火山灰が酒匂川の本流をせき止めた。翌年の梅雨の増水で一気に流れ出し、谷口の堤防が切れた。", "source_url": "https://kotobank.jp/word/酒匂川", "source_title": "コトバンク「酒匂川」（日本大百科全書）"}, {"pref": "神奈川", "kind": "恵み", "era": "江戸", "year": 1859, "title": "横浜開港", "text": "日米修好通商条約にもとづき、農漁村だった横浜村が開港場となった。運上所と波止場が設けられ、外国貿易が始まった。", "source_url": "https://kotobank.jp/word/横浜港", "source_title": "コトバンク「横浜港」（日本歴史地名大系・日本大百科全書）／「横浜市」（ブリタニカ）"}, {"pref": "神奈川", "kind": "恵み", "era": "明治", "year": 1887, "title": "横浜水道の完成", "text": "相模川の道志川合流点付近から水を引く横浜水道が完成した。日本最初の洋式水道とされる。", "source_url": "https://kotobank.jp/word/横浜水道", "source_title": "コトバンク「横浜水道」（世界大百科事典「相模川」「神奈川県」）"}, {"pref": "神奈川", "kind": "災い", "era": "大正", "year": 1923, "title": "関東大震災", "text": "相模湾北部を震源とする大地震で、神奈川県では家屋の倒壊が特に多く、横浜では火災が広がった。沿岸は津波に襲われ、根府川では土石流が起きた。", "source_url": "https://kotobank.jp/word/関東大震災", "source_title": "コトバンク「関東大震災」（改訂新版世界大百科事典・日本大百科全書・山川日本史小辞典）"}, {"pref": "神奈川", "kind": "災い", "era": "昭和", "year": 1945, "title": "横浜大空襲", "text": "五月二十九日の朝、多数のB29が横浜の市街に焼夷弾を落とした。死者の数は記録によって大きく異なり、実態は分かっていない。", "source_url": "https://kotobank.jp/word/横浜大空襲", "source_title": "コトバンク「横浜大空襲」（共同通信ニュース用語解説）"}, {"pref": "長崎", "kind": "災い", "era": "平安", "year": 1019, "title": "刀伊の入寇", "text": "刀伊の船団が対馬・壱岐を襲い、多くの島民が殺されたり捕らえられたりした。壱岐では国守の藤原理忠も殺され、そのあと一団は筑前へ侵入した。", "source_url": "https://kotobank.jp/word/刀伊の入寇", "source_title": "コトバンク「刀伊の入寇」（日本大百科全書・改訂新版世界大百科事典・山川日本史小辞典）"}, {"pref": "長崎", "kind": "災い", "era": "中世", "year": 1274, "title": "文永の役、対馬・壱岐の戦い", "text": "元・高麗の軍が十月に対馬に上陸して地頭代宗資国らを討ち、続いて壱岐を襲って守護代平景隆らが戦死した。", "source_url": "https://kotobank.jp/word/文永の役", "source_title": "コトバンク「文永の役」（山川日本史小辞典）"}, {"pref": "長崎", "kind": "恵み", "era": "中世", "year": 1571, "title": "長崎にポルトガル船が入る", "text": "長崎にポルトガル船が入港し、以後、長崎は海外との貿易港として急速に発展した。", "source_url": "https://kotobank.jp/word/長崎市", "source_title": "コトバンク「長崎市」（ブリタニカ国際大百科事典）"}, {"pref": "長崎", "kind": "災い", "era": "江戸", "year": 1637, "title": "島原の乱", "text": "重い年貢と凶作、キリシタンへの弾圧に苦しんだ人々が蜂起して原城に籠った。幕府の大軍の総攻撃で落城し、籠城した人々はほとんど殺された。", "source_url": "https://kotobank.jp/word/島原の乱", "source_title": "コトバンク「島原の乱」（改訂新版世界大百科事典・山川日本史小辞典・マイペディアほか）"}, {"pref": "長崎", "kind": "恵み", "era": "江戸", "year": 1641, "title": "オランダ商館の出島移転", "text": "オランダの商館が平戸から長崎の出島へ移された。出島はもとはポルトガル人を隔てて住まわせるため、長崎の商人たちに造らせた扇形の埋め立て地だった。", "source_url": "https://kotobank.jp/word/出島", "source_title": "コトバンク「出島」（日本大百科全書・山川日本史小辞典・世界大百科事典ほか）"}, {"pref": "長崎", "kind": "災い", "era": "江戸", "year": 1792, "title": "島原大変肥後迷惑", "text": "雲仙岳の噴火活動にともない眉山が崩れ、土砂が島原に流れ込んだ。有明海に起きた津波は対岸の肥後天草にも被害を及ぼした。", "source_url": "https://kotobank.jp/word/島原大変肥後迷惑", "source_title": "コトバンク「島原大変肥後迷惑」（デジタル大辞泉）"}, {"pref": "長崎", "kind": "恵み", "era": "明治", "year": 1891, "title": "本河内高部水道の給水開始", "text": "本河内高部水道が完成し、五月から給水を始めた。日本で三番目の近代水道とされる。", "source_url": "https://www.city.nagasaki.lg.jp/syokai/750000/757000/p007004.html", "source_title": "長崎市「歴史年表 明治時代・大正時代」"}, {"pref": "長崎", "kind": "道がひらく", "era": "明治", "year": 1897, "title": "九州鉄道が長崎へ", "text": "九州鉄道が長崎〜長与間で開通した。当時の長崎駅は浦上にあり、1905年に長崎〜浦上間も開通した。", "source_url": "https://www.city.nagasaki.lg.jp/syokai/750000/757000/p007004.html", "source_title": "長崎市「歴史年表 明治時代・大正時代」"}, {"pref": "長崎", "kind": "道がひらく", "era": "大正", "year": 1915, "title": "長崎に路面電車", "text": "浦上〜築町間に路面電車が開通した。", "source_url": "https://www.city.nagasaki.lg.jp/syokai/750000/757000/p007004.html", "source_title": "長崎市「歴史年表 明治時代・大正時代」"}, {"pref": "長崎", "kind": "道がひらく", "era": "大正", "year": 1923, "title": "日華連絡船の就航", "text": "日華連絡船の長崎丸が、長崎〜上海間に就航した。", "source_url": "https://www.city.nagasaki.lg.jp/syokai/750000/757000/p007004.html", "source_title": "長崎市「歴史年表 明治時代・大正時代」"}, {"pref": "長崎", "kind": "災い", "era": "昭和", "year": 1945, "title": "長崎への原子爆弾投下", "text": "八月、長崎に原子爆弾が投下され、市街の多くが破壊され、多数の死傷者が出た。", "source_url": "https://kotobank.jp/word/長崎市", "source_title": "コトバンク「長崎市」（ブリタニカ国際大百科事典）"}, {"pref": "宮崎", "kind": "災い", "era": "中世", "year": 1578, "title": "耳川の戦い", "text": "日向の高城を囲んだ大友軍が、救援に来た島津軍と耳川付近で激突し、伏兵に崩されて大敗した。", "source_url": "https://kotobank.jp/word/耳川の戦", "source_title": "コトバンク「耳川の戦」（改訂新版世界大百科事典・百科事典マイペディア）"}, {"pref": "宮崎", "kind": "恵み", "era": "中世", "year": 1587, "title": "秀吉の九州統一と延岡", "text": "豊臣秀吉の九州統一ののち、延岡は高橋氏らが治める城下町となった。以後藩主はめまぐるしく替わった。", "source_url": "https://kotobank.jp/word/延岡市", "source_title": "コトバンク「延岡市」（ブリタニカ国際大百科事典）"}, {"pref": "宮崎", "kind": "災い", "era": "江戸", "year": 1662, "title": "外所地震", "text": "日向灘の大地震で宮崎市南部の集落を津波が襲い、外所の集落が埋没した。「とんところ地震」とも呼ばれる。", "source_url": "https://nied-repo.bosai.go.jp/records/2287", "source_title": "防災科学技術研究所研究資料第467号「1662年日向灘地震における供養碑及び歴史的資産に関する研究」（2021）"}, {"pref": "宮崎", "kind": "道がひらく", "era": "大正", "year": 1923, "title": "日豊本線の開通", "text": "日豊本線が開通し、延岡は県北部の物資の集散地となった。", "source_url": "https://kotobank.jp/word/延岡市", "source_title": "コトバンク「延岡市」（ブリタニカ国際大百科事典）"}, {"pref": "山形", "kind": "災い", "era": "中世", "year": 1600, "title": "長谷堂城の戦い", "text": "上杉景勝の大軍が長谷堂城を攻めたが、関ヶ原で西軍が敗れたため上杉勢は撤退し、最上方が城を守りきった。", "source_url": "https://kotobank.jp/word/長谷堂城", "source_title": "コトバンク「長谷堂城」（日本の城がわかる事典）"}, {"pref": "山形", "kind": "災い", "era": "明治", "year": 1874, "title": "ワッパ騒動", "text": "酒田県の庄内で、農民が貢租の過納金の払戻しを求めて立ち上がり、石代会社を作って酒田の商人森藤右衛門の指導で争った。", "source_url": "https://kotobank.jp/word/ワッパ一揆", "source_title": "コトバンク「ワッパ一揆」（改訂新版世界大百科事典・百科事典マイペディア）"}, {"pref": "山形", "kind": "災い", "era": "明治", "year": 1894, "title": "庄内地震", "text": "10月22日、庄内平野の地下で大きな地震が起きた。酒田の町では火事が大きく広がり、焼けて亡くなった人も少なくなかった。", "source_url": "https://kotobank.jp/word/庄内地震", "source_title": "コトバンク「庄内地震」（デジタル大辞泉プラス）"}, {"pref": "山形", "kind": "道がひらく", "era": "大正", "year": 1913, "title": "酒田線（陸羽西線）の開業", "text": "酒田線の名で新庄から古口までが開業し、次の年に余目、さらに酒田まで延びた。奥羽本線と庄内平野が初めて線路でつながった。", "source_url": "https://kotobank.jp/word/陸羽西線", "source_title": "コトバンク「陸羽西線」（日本大百科全書(ニッポニカ)・精選版日本国語大辞典）"}, {"pref": "山形", "kind": "道がひらく", "era": "昭和", "year": 1937, "title": "仙山線の全通", "text": "仙山トンネルが開通し、仙台と山形を結ぶ仙山線が全通した。作並―山寺間は東北の旧国鉄線で最初の電化区間だった。", "source_url": "https://kotobank.jp/word/仙山線", "source_title": "コトバンク「仙山線」（日本大百科全書(ニッポニカ)・精選版日本国語大辞典）"}, {"pref": "石川", "kind": "災い", "era": "平安", "year": 1177, "title": "白山宮末寺の焼き払いと抗議", "text": "加賀守藤原師高の弟で目代の師経が、白山宮の中宮に属する寺を焼いた。これに抗議して中宮3社の衆徒や神人が立ち上がり、本寺の延暦寺を動かして強訴に及んだ。", "source_url": "https://kotobank.jp/word/加賀国", "source_title": "コトバンク「加賀国」（改訂新版世界大百科事典）"}, {"pref": "石川", "kind": "災い", "era": "中世", "year": 1488, "title": "加賀一向一揆（長享の一揆）", "text": "一向一揆が守護富樫政親を高尾城に滅ぼし、本願寺門徒が国を治める「百姓の持ちたる国」が生まれた。", "source_url": "https://kotobank.jp/word/加賀一向一揆", "source_title": "コトバンク「加賀一向一揆」（百科事典マイペディア・日本大百科全書(ニッポニカ)・世界大百科事典）"}, {"pref": "石川", "kind": "恵み", "era": "江戸", "year": 1661, "title": "輪島塗の「地の粉」の発見", "text": "寛文年間に輪島で「地の粉」が見つかり、堅牢な下地づくりに成功した。享保のころには沈金も始まった。", "source_url": "https://kotobank.jp/word/輪島塗", "source_title": "コトバンク「輪島塗」（日本大百科全書(ニッポニカ)・改訂新版世界大百科事典）"}, {"pref": "石川", "kind": "道がひらく", "era": "明治", "year": 1898, "title": "金沢と七尾に鉄道が届く", "text": "北陸線が4月に金沢まで延び、同じ年に七尾鉄道が津幡―七尾間で開業して、能登へも鉄道が通じた。", "source_url": "https://kotobank.jp/word/北陸本線", "source_title": "コトバンク「北陸本線」（改訂新版世界大百科事典）・「七尾線」（日本大百科全書(ニッポニカ)ほか）"}, {"pref": "石川", "kind": "恵み", "era": "明治", "year": 1881, "title": "尾小屋鉱山の本格経営", "text": "1879年に新しい銅床が2か所見つかり、1881年には旧金沢藩の重臣だった横山家が鉱山を引き受けた。明治40年代には国内で指折りの銅山に育った。", "source_url": "https://kotobank.jp/word/尾小屋鉱山", "source_title": "コトバンク「尾小屋鉱山」（百科事典マイペディア）"}, {"pref": "石川", "kind": "道がひらく", "era": "大正", "year": 1925, "title": "七尾線の輪島への延長", "text": "七尾から能登半島の奥へ向けて線路の延長開業が始まり、昭和10年に輪島まで通じた。", "source_url": "https://kotobank.jp/word/七尾線", "source_title": "コトバンク「七尾線」（日本大百科全書(ニッポニカ)・百科事典マイペディア）"}, {"pref": "石川", "kind": "災い", "era": "昭和", "year": 1934, "title": "手取川の大水害", "text": "加賀平野を流れる手取川がはんらんし、歴史に残る大水害をもたらした。平安後期から用水が引かれてきた川である。", "source_url": "https://kotobank.jp/word/手取川", "source_title": "コトバンク「手取川」（改訂新版世界大百科事典・日本歴史地名大系）"}, {"pref": "鳥取", "kind": "災い", "era": "中世", "year": 1581, "title": "鳥取城の兵糧攻め", "text": "羽柴秀吉の大軍に囲まれた鳥取城は兵糧攻めで食糧が尽き、毛利方の吉川経家が降伏して開城した。", "source_url": "https://kotobank.jp/word/鳥取城", "source_title": "コトバンク「鳥取城」（日本の城がわかる事典・日本大百科全書(ニッポニカ)・世界大百科事典）"}, {"pref": "鳥取", "kind": "災い", "era": "江戸", "year": 1717, "title": "日野郡から広がった救米一揆", "text": "2月、日野郡で救米を求める大規模な一揆が起こり、伯耆国全郡と因幡国の気多・高草二郡にも広がった。", "source_url": "https://kotobank.jp/word/元文一揆", "source_title": "コトバンク「元文一揆」所収 世界大百科事典（旧版）【鳥取藩元文一揆】"}, {"pref": "鳥取", "kind": "道がひらく", "era": "大正", "year": 1919, "title": "因美線の開業", "text": "鳥取から千代川沿いに南へ向かう因美線の開業が始まり、昭和7年に全通して鳥取平野と津山盆地が結ばれた。", "source_url": "https://kotobank.jp/word/因美線", "source_title": "コトバンク「因美線」（日本大百科全書(ニッポニカ)・百科事典マイペディア）"}, {"pref": "鳥取", "kind": "災い", "era": "昭和", "year": 1943, "title": "鳥取地震", "text": "9月10日夕方、鳥取市付近を震源とする地震が起きた。地盤の弱い沖積地で被害が大きかった。", "source_url": "https://kotobank.jp/word/鳥取地震", "source_title": "コトバンク「鳥取地震」（デジタル大辞泉・日本大百科全書(ニッポニカ)・最新地学事典・世界大百科事典）"}, {"pref": "山梨", "kind": "恵み", "era": "中世", "year": 1542, "title": "信玄堤の着工", "text": "大洪水をきっかけに武田信玄が釜無川の治水に着手。御勅使川の流れを分けて堤と霞堤を築いた。", "source_url": "https://kotobank.jp/word/信玄堤", "source_title": "コトバンク「信玄堤」（改訂新版世界大百科事典・日本大百科全書(ニッポニカ)・日本歴史地名大系）"}, {"pref": "山梨", "kind": "災い", "era": "江戸", "year": 1836, "title": "甲州騒動（天保騒動）", "text": "凶作と暴風で米価が上がり、困窮した都留郡の百姓が米価引下げを求めて立った。打ちこわしは甲斐国幕領全域に及んだ。", "source_url": "https://kotobank.jp/word/甲州騒動", "source_title": "コトバンク「甲州騒動」（山川日本史小辞典 改訂新版）"}, {"pref": "山梨", "kind": "恵み", "era": "明治", "year": 1877, "title": "大日本山梨葡萄酒会社の設立", "text": "甲州の高野正誠と土屋龍憲の手で、大日本山梨葡萄酒会社が興された。二人はフランスへ渡り、現地でワインの造り方を学んだ。", "source_url": "https://www.mlit.go.jp/tagengo-db/common/001557420.pdf", "source_title": "観光庁 地域観光資源の多言語解説文データベース（甲州のワイン関連）"}, {"pref": "山梨", "kind": "道がひらく", "era": "明治", "year": 1903, "title": "中央線が甲府に届く", "text": "八王子側から延びてきた中央東線が6月に甲府まで開業した。3年後には塩尻まで延びた。", "source_url": "https://kotobank.jp/word/中央本線", "source_title": "コトバンク「中央本線」（改訂新版世界大百科事典）"}, {"pref": "山梨", "kind": "道がひらく", "era": "大正", "year": 1913, "title": "富士身延鉄道の開業", "text": "富士から富士川沿いに富士身延鉄道が順次開業し、身延まで達した。", "source_url": "https://kotobank.jp/word/身延線", "source_title": "コトバンク「身延線」（改訂新版世界大百科事典・日本大百科全書(ニッポニカ)）"}, {"pref": "山梨", "kind": "道がひらく", "era": "昭和", "year": 1928, "title": "身延線の全通", "text": "甲府―市川大門間が開通し、富士と甲府が富士川沿いの鉄道で結ばれた。", "source_url": "https://kotobank.jp/word/身延線", "source_title": "コトバンク「身延線」（改訂新版世界大百科事典・日本大百科全書ほか）"}, {"pref": "大阪", "kind": "恵み", "era": "平安", "year": 805, "title": "摂津国府の移転と渡辺津", "text": "摂津国府が移り、淀川河口の渡辺津は国府の港として往来が増えた。熊野詣の人々も船で下りここで上陸した。", "source_url": "https://kotobank.jp/word/渡辺津", "source_title": "コトバンク「渡辺津」（日本歴史地名大系・百科事典マイペディア）"}, {"pref": "大阪", "kind": "災い", "era": "中世", "year": 1570, "title": "石山合戦", "text": "石山本願寺が織田信長と戦い、諸国の門徒に蜂起を促した。講和により本願寺は紀州鷺森に移り、そのさい寺内は炎上した。", "source_url": "https://kotobank.jp/word/石山合戦", "source_title": "コトバンク「石山合戦」（山川日本史小辞典・ブリタニカ国際大百科事典・世界大百科事典）"}, {"pref": "大阪", "kind": "恵み", "era": "江戸", "year": 1730, "title": "堂島米市場の公認", "text": "堂島の帳合米取引が公認された。ここで立った米相場が全国の基準となり、物価にも大きな影響を与えた。", "source_url": "https://kotobank.jp/word/堂島米市場", "source_title": "コトバンク「堂島米市場」（日本大百科全書(ニッポニカ)・改訂新版世界大百科事典・山川日本史小辞典）"}, {"pref": "大阪", "kind": "災い", "era": "江戸", "year": 1837, "title": "大塩平八郎の乱", "text": "天保の飢饉で大坂にも餓死者が出る中、奉行所の無策に憤った大塩平八郎が挙兵し、兵火が大坂市中を焼いた。", "source_url": "https://kotobank.jp/word/大塩平八郎の乱", "source_title": "コトバンク「大塩平八郎の乱」（日本大百科全書(ニッポニカ)・ブリタニカ国際大百科事典・旺文社日本史事典）"}, {"pref": "大阪", "kind": "災い", "era": "大正", "year": 1918, "title": "米騒動が大阪に及ぶ", "text": "富山から広がった米騒動が大阪市にも及び、いっそう大規模な暴動となった。鎮圧のため軍隊が出動した。", "source_url": "https://kotobank.jp/word/米騒動", "source_title": "コトバンク「米騒動」（日本大百科全書(ニッポニカ)・改訂新版世界大百科事典）"}, {"pref": "大阪", "kind": "災い", "era": "昭和", "year": 1934, "title": "室戸台風", "text": "9月21日、室戸台風が大阪湾に高潮をもたらした。多くの木造の小学校が倒れ、先生や子どもが下敷きとなって命を失った。", "source_url": "https://kotobank.jp/word/室戸台風", "source_title": "コトバンク「室戸台風」（改訂新版世界大百科事典・日本大百科全書(ニッポニカ)・百科事典マイペディア）"}, {"pref": "大阪", "kind": "道がひらく", "era": "昭和", "year": 1937, "title": "御堂筋の完成", "text": "1925年から都市計画で道を広げてきた御堂筋が仕上がった。工事のあいだに、大阪初の市営地下鉄として御堂筋線も走り出した。", "source_url": "https://kotobank.jp/word/御堂筋", "source_title": "コトバンク「御堂筋」（改訂新版世界大百科事典・共同通信ニュース用語解説ほか）"}, {"pref": "和歌山", "kind": "行事", "era": "平安", "year": 907, "title": "熊野御幸の始まり", "text": "宇多法皇の参詣に始まり、院政期には上皇がたびたび熊野へ詣でた。参詣は「蟻の熊野詣」の諺をうむほど盛んになった。", "source_url": "https://kotobank.jp/word/熊野詣", "source_title": "コトバンク「熊野詣」（改訂新版世界大百科事典・精選版日本国語大辞典・山川日本史小辞典）"}, {"pref": "和歌山", "kind": "災い", "era": "中世", "year": 1585, "title": "根来寺の焼き討ち", "text": "鉄砲を重要な戦力とする武力集団を抱えた根来寺が、豊臣秀吉の紀州攻めで焼かれ、伽藍のほとんどが失われた。", "source_url": "https://kotobank.jp/word/根来寺", "source_title": "コトバンク「根来寺」（日本大百科全書(ニッポニカ)・改訂新版世界大百科事典ほか）"}, {"pref": "和歌山", "kind": "恵み", "era": "江戸", "year": 1815, "title": "湯浅の醤油づくり", "text": "湯浅の醤油は紀州藩の御仕入方商品として保護と統制を受けた。文化12年には湯浅村・広村・栖原村で造られていた。", "source_url": "https://kotobank.jp/word/湯浅醤油", "source_title": "コトバンク「湯浅醤油」（日本大百科全書(ニッポニカ)・世界大百科事典）"}, {"pref": "和歌山", "kind": "災い", "era": "明治", "year": 1890, "title": "エルトゥールル号の遭難", "text": "9月16日、オスマン帝国の軍艦エルトゥールル号が台風に遭い、樫野崎の沖で遭難した。地元の人々が手分けして亡きがらや遺品を引き上げた。", "source_url": "https://www.bunka.go.jp/kindai/todai/071/index.html", "source_title": "文化庁「樫野埼灯台及びエルトゥールル号遭難事件遺跡」"}, {"pref": "和歌山", "kind": "道がひらく", "era": "大正", "year": 1912, "title": "新宮鉄道の開業", "text": "新宮鉄道が新宮―紀伊勝浦間で開業した。のちに紀勢本線の一部となる区間である。", "source_url": "https://kotobank.jp/word/紀勢本線", "source_title": "コトバンク「紀勢本線」（日本大百科全書(ニッポニカ)）"}, {"pref": "和歌山", "kind": "災い", "era": "大正", "year": 1918, "title": "米騒動が和歌山に及ぶ", "text": "富山県から全国へ広がった米騒動が和歌山県でも続発し、和歌山には鎮圧のため軍隊が出動した。", "source_url": "https://kotobank.jp/word/米騒動", "source_title": "コトバンク「米騒動」（日本大百科全書(ニッポニカ)・改訂新版世界大百科事典）"}, {"pref": "和歌山", "kind": "道がひらく", "era": "大正", "year": 1924, "title": "紀勢西線の開通", "text": "紀勢西線が和歌山から箕島まで開通した。以後、線路は紀伊半島の海沿いを南へ延びていった。", "source_url": "https://kotobank.jp/word/紀勢本線", "source_title": "コトバンク「紀勢本線」（改訂新版世界大百科事典・日本大百科全書(ニッポニカ)）"}, {"pref": "和歌山", "kind": "道がひらく", "era": "昭和", "year": 1940, "title": "紀勢西線が紀伊木本へ", "text": "和歌山から南へ延びてきた紀勢西線が、昭和15年までに紀伊木本に達した。", "source_url": "https://kotobank.jp/word/紀勢本線", "source_title": "コトバンク「紀勢本線」（改訂新版世界大百科事典・ブリタニカ国際大百科事典・日本大百科全書(ニッポニカ)）"}, {"pref": "熊本", "kind": "災い", "era": "中世", "year": 1587, "title": "肥後国衆一揆", "text": "肥後の領主となった佐々成政が検地を強行し、隈部親永ら国人衆が反対の一揆を起こした。成政は責めを負って失脚した。", "source_url": "https://kotobank.jp/word/佐々成政", "source_title": "コトバンク「佐々成政」（世界大百科事典（旧版）【肥後一揆】【肥後国】・日本大百科全書(ニッポニカ)ほか）"}, {"pref": "熊本", "kind": "災い", "era": "明治", "year": 1876, "title": "神風連の乱", "text": "10月24日夜、熊本の敬神党が廃刀令などに反発して蜂起し、熊本鎮台や県令宅を襲ったが、翌日鎮圧された。", "source_url": "https://kotobank.jp/word/神風連の乱", "source_title": "コトバンク「神風連の乱」（日本大百科全書(ニッポニカ)・山川日本史小辞典ほか）"}, {"pref": "熊本", "kind": "災い", "era": "明治", "year": 1877, "title": "西南戦争と熊本城", "text": "西南戦争で谷干城らの政府軍が熊本城に籠城して守り抜いた。城は天守を含む主要な建物を失っていた。", "source_url": "https://kotobank.jp/word/熊本城", "source_title": "コトバンク「熊本城」（旺文社日本史事典・ブリタニカ国際大百科事典・日本の城がわかる事典）"}, {"pref": "熊本", "kind": "恵み", "era": "明治", "year": 1887, "title": "三角西港の完成", "text": "宇土半島の先にオランダ式の三角西港が完成した。明治初期のオランダ式築港で最も成功した港とされる。", "source_url": "https://kotobank.jp/word/三角西港", "source_title": "コトバンク「三角西港」（百科事典マイペディア・事典日本の地域遺産）"}, {"pref": "熊本", "kind": "恵み", "era": "明治", "year": 1908, "title": "水俣にカーバイド工場", "text": "1908年、日本窒素肥料が水俣にカーバイド（炭化カルシウム）をつくる工場を建てた。町は第二次世界大戦で被害を受けたが、戦後に立ち直って大きく伸びた。", "source_url": "https://kotobank.jp/word/水俣市", "source_title": "コトバンク「水俣市」（ブリタニカ国際大百科事典）"}, {"pref": "熊本", "kind": "災い", "era": "大正", "year": 1918, "title": "米騒動の終わり", "text": "9月12日、熊本県の万田炭鉱で起きた暴動を最後に、全国に広がった米騒動はいちおう終結した。", "source_url": "https://kotobank.jp/word/米騒動", "source_title": "コトバンク「米騒動」（日本大百科全書(ニッポニカ)）"}, {"pref": "熊本", "kind": "道がひらく", "era": "昭和", "year": 1928, "title": "豊肥本線の全通", "text": "宮地―玉来間が開業し、熊本と大分が阿蘇を越える鉄道で結ばれて豊肥本線となった。", "source_url": "https://kotobank.jp/word/豊肥本線", "source_title": "コトバンク「豊肥本線」（日本大百科全書(ニッポニカ)・改訂新版世界大百科事典ほか）"}, {"pref": "沖縄", "kind": "道がひらく", "era": "大正", "year": 1914, "title": "沖縄県営鉄道の創業", "text": "沖縄県営鉄道が創業し、那覇から与那原・嘉手納・糸満、那覇港へと線路が延びた。のちに沖縄戦で破壊された。", "source_url": "https://kotobank.jp/word/沖縄県営鉄道", "source_title": "コトバンク「沖縄県営鉄道」所収 世界大百科事典（旧版）【沖縄県】【那覇市】"}, {"pref": "宮城", "kind": "災い", "era": "平安", "year": 869, "title": "貞観地震", "text": "陸奥国を大地震が襲い、立っていられないほどの揺れのあと、大津波が多賀城の城下に押し寄せた。", "source_url": "https://kotobank.jp/word/貞観地震", "source_title": "コトバンク「貞観地震」（ニッポニカ・ブリタニカ）"}, {"pref": "宮城", "kind": "災い", "era": "平安", "year": 1051, "title": "前九年の役", "text": "陸奥の安倍氏が国司に背き、源頼義・義家と戦った。鬼切部では安倍氏が国司の軍を破っている。", "source_url": "https://kotobank.jp/word/前九年の役", "source_title": "コトバンク「前九年の役」（世界大百科・大辞泉ほか）"}, {"pref": "宮城", "kind": "災い", "era": "中世", "year": 1590, "title": "葛西大崎一揆", "text": "領地を没収された葛西・大崎の旧領で、検地を強いる新領主に旧臣や農民が蜂起した。伊達政宗が佐沼城・登米城を攻めて鎮めた。", "source_url": "https://kotobank.jp/word/葛西大崎一揆", "source_title": "コトバンク「葛西大崎一揆」（世界大百科・マイペディア）"}, {"pref": "宮城", "kind": "災い", "era": "江戸", "year": 1611, "title": "慶長三陸地震津波", "text": "三陸沖の地震で起きた津波が仙台平野の内陸深くまで入り込み、海岸から離れた荒浜の集落も大きな被害を受けた。", "source_url": "https://kotobank.jp/word/慶長三陸地震", "source_title": "コトバンク「慶長三陸地震」（ニッポニカ）"}, {"pref": "宮城", "kind": "道がひらく", "era": "明治", "year": 1887, "title": "東北本線の開通", "text": "上野から仙台を経て塩釜までの鉄道が開通した。同じ年、仙台に第二高等中学校も創立されている。", "source_url": "https://www.city.sendai.jp/sesakukoho/shise/gaiyo/profile/ayumi.html", "source_title": "仙台市「仙台市のあゆみ」"}, {"pref": "宮城", "kind": "道がひらく", "era": "昭和", "year": 1926, "title": "仙台市電の開通", "text": "大正15年（1926）、仙台市電が開通した。仙台市営交通の出発点である。", "source_url": "https://www.city.sendai.jp/sesakukoho/shise/gaiyo/profile/ayumi.html", "source_title": "仙台市「仙台市のあゆみ」"}, {"pref": "宮城", "kind": "災い", "era": "昭和", "year": 1945, "title": "仙台空襲", "text": "7月10日の空襲で仙台の市中心部が全焼した。", "source_url": "https://www.city.sendai.jp/sesakukoho/shise/gaiyo/profile/ayumi.html", "source_title": "仙台市「仙台市のあゆみ」"}, {"pref": "富山", "kind": "災い", "era": "平安", "year": 1183, "title": "倶利伽羅峠の戦い", "text": "越中と加賀の境の倶利伽羅峠で、源義仲が平氏の追討軍を夜戦で破った。角に松明をつけた牛の話が『源平盛衰記』に残る。", "source_url": "https://kotobank.jp/word/倶利伽羅峠の戦", "source_title": "コトバンク「倶利伽羅峠の戦」（山川・マイペディア）"}, {"pref": "富山", "kind": "災い", "era": "中世", "year": 1390, "title": "瑞泉寺の創建", "text": "本願寺5世綽如が井波に瑞泉寺を開いた。のちに戦国期の越中で、一向一揆の中心となる寺である。", "source_url": "https://kotobank.jp/word/瑞泉寺", "source_title": "コトバンク「瑞泉寺」（ニッポニカ・マイペディアほか）"}, {"pref": "富山", "kind": "災い", "era": "中世", "year": 1581, "title": "佐々成政の瑞泉寺攻め", "text": "越中を治めた佐々成政が、一向一揆の頭目だった瑞泉寺を攻め落とした。", "source_url": "https://kotobank.jp/word/瑞泉寺", "source_title": "コトバンク「瑞泉寺」（ニッポニカ・マイペディア）"}, {"pref": "富山", "kind": "災い", "era": "江戸", "year": 1858, "title": "飛越地震と常願寺川の大洪水", "text": "安政の大地震で立山の大鳶山・小鳶山が崩れ、川がせき止められた。2回目の決壊で富山平野に大洪水が押し寄せた。", "source_url": "https://www.bousai.go.jp/kyoiku/kyokun/kyoukunnokeishou/rep/1858_hietsu_jishin/index.html", "source_title": "内閣府防災「災害教訓の継承に関する専門調査会報告書 1858 飛越地震」"}, {"pref": "富山", "kind": "災い", "era": "明治", "year": 1869, "title": "ばんどり騒動", "text": "凶作の年に加賀藩が年貢の取り立てを強めたため、新川郡の農民が蓑をまとって蜂起し、役人の家などを打ちこわした。", "source_url": "https://kotobank.jp/word/ばんどり騒動", "source_title": "コトバンク「ばんどり騒動」（世界大百科・ニッポニカ）"}, {"pref": "富山", "kind": "災い", "era": "大正", "year": 1918, "title": "米騒動の始まり", "text": "米価が上がるなか、魚津町の漁民の妻たちが米の県外移出を止めようと海岸に集まった。騒ぎは富山湾沿岸から全国へ広がった。", "source_url": "https://kotobank.jp/word/米騒動", "source_title": "コトバンク「米騒動」（世界大百科・ニッポニカほか）"}, {"pref": "富山", "kind": "災い", "era": "昭和", "year": 1945, "title": "富山大空襲", "text": "8月2日未明、米軍のB29が富山市に焼夷弾を落とし、目標となった市街地が焼き尽くされた。", "source_url": "https://kotobank.jp/word/富山大空襲", "source_title": "コトバンク「富山大空襲」（共同通信ニュース用語解説）"}, {"pref": "兵庫", "kind": "災い", "era": "平安", "year": 1184, "title": "一ノ谷の戦い", "text": "福原から一ノ谷に陣を構えた平氏を源範頼・義経が攻めた。義経の鵯越の奇襲で、平氏は海へ逃れた。", "source_url": "https://kotobank.jp/word/一ノ谷の戦", "source_title": "コトバンク「一ノ谷の戦」（世界大百科・山川ほか）"}, {"pref": "兵庫", "kind": "災い", "era": "中世", "year": 1336, "title": "湊川の戦い", "text": "九州から攻め上った足利尊氏・直義の軍が、兵庫の湊川で新田義貞・楠木正成と戦った。孤立した正成は一族と自害した。", "source_url": "https://kotobank.jp/word/湊川の戦", "source_title": "コトバンク「湊川の戦」（世界大百科・山川ほか）"}, {"pref": "兵庫", "kind": "災い", "era": "中世", "year": 1441, "title": "嘉吉の乱", "text": "播磨守護の赤松満祐が京都の自邸で将軍足利義教を殺し、播磨へ下った。幕府の討伐軍に攻められ、9月に自害した。", "source_url": "https://kotobank.jp/word/嘉吉の乱", "source_title": "コトバンク「嘉吉の乱」（ニッポニカ・世界大百科ほか）"}, {"pref": "兵庫", "kind": "恵み", "era": "江戸", "year": 1821, "title": "姫路木綿の専売", "text": "借金に苦しむ姫路藩は家老河合寸翁のもとで木綿の専売に取り組み、国産会所を開いて江戸での専売権を得た。", "source_url": "https://kotobank.jp/word/姫路藩", "source_title": "コトバンク「姫路藩」（世界大百科・ニッポニカ）"}, {"pref": "兵庫", "kind": "恵み", "era": "明治", "year": 1868, "title": "兵庫（神戸）開港", "text": "慶応3年12月7日（1868年1月1日）、生田川の河口にあった神戸の浦に港が開かれ、外国の船を迎える港となった。名を神戸港と改めたのは1872年のこと。", "source_url": "https://kotobank.jp/word/神戸港", "source_title": "コトバンク「神戸港」（大辞泉・マイペディア・ブリタニカ）"}, {"pref": "兵庫", "kind": "道がひらく", "era": "明治", "year": 1888, "title": "山陽鉄道の開業", "text": "山陽鉄道が兵庫―明石間で開業し、西へ線路を延ばしていった。1901年には馬関（下関）まで全通する。", "source_url": "https://kotobank.jp/word/山陽鉄道", "source_title": "コトバンク「山陽鉄道」（ニッポニカ・山川ほか）"}, {"pref": "兵庫", "kind": "災い", "era": "大正", "year": 1918, "title": "米騒動と鈴木商店焼打ち", "text": "米騒動のさなか、鈴木商店が米を買い占めて値をつり上げているとの噂が立ち、神戸の本店が焼き打ちにあった。", "source_url": "https://kotobank.jp/word/米騒動", "source_title": "コトバンク「米騒動」（世界大百科旧版「鈴木商店」・ニッポニカ）"}, {"pref": "兵庫", "kind": "災い", "era": "昭和", "year": 1938, "title": "阪神大水害", "text": "7月3〜5日、台風に刺激された梅雨前線の集中豪雨で川があふれ、土石流が神戸の市街地に流れ込んだ。", "source_url": "https://www.city.kobe.lg.jp/a43553/kurashi/machizukuri/river/suigaisonae/02kako_02.html", "source_title": "神戸市「過去の水害」（昭和13年阪神大水害）"}, {"pref": "兵庫", "kind": "災い", "era": "昭和", "year": 1945, "title": "神戸空襲", "text": "神戸は数回にわたって空襲を受けた。3月には市の西半分が壊滅し、6月には東半分と西宮市が焼夷弾で焼かれた。", "source_url": "https://kotobank.jp/word/神戸空襲", "source_title": "コトバンク「神戸空襲」（共同通信ニュース用語解説）"}, {"pref": "東京", "kind": "災い", "era": "平安", "year": 938, "title": "武蔵武芝と国司の争い", "text": "武蔵国足立郡の郡司だった武蔵武芝は、新たに来た国司の興世王（権守）・源経基（介）ともめた。平将門が間に入ったものの、手違いもあって仲直りはならなかった。", "source_url": "https://kotobank.jp/word/武蔵武芝", "source_title": "コトバンク「武蔵武芝」（ニッポニカ・日本人名大辞典）"}, {"pref": "東京", "kind": "災い", "era": "江戸", "year": 1772, "title": "目黒行人坂の大火", "text": "目黒行人坂の大円寺から出た火が、麻布・芝・日本橋・本郷・浅草などへ燃え広がり、千住にまで達した。", "source_url": "https://kotobank.jp/word/目黒行人坂の大火", "source_title": "コトバンク「目黒行人坂の大火」（世界大百科）"}, {"pref": "東京", "kind": "道がひらく", "era": "大正", "year": 1914, "title": "東京駅の開業", "text": "12月、辰野金吾らの設計による煉瓦造りの東京駅が、東海道本線の起点として営業を始めた。", "source_url": "https://kotobank.jp/word/東京駅", "source_title": "コトバンク「東京駅」（世界大百科・ブリタニカ・ニッポニカ）"}, {"pref": "奈良", "kind": "災い", "era": "平安", "year": 1180, "title": "南都焼打", "text": "12月28日の夜、平氏の討伐軍が奈良の市中に火を放って攻め込み、東大寺と興福寺を焼いた。", "source_url": "https://kotobank.jp/word/南都焼打", "source_title": "コトバンク「南都焼打」（山川）"}, {"pref": "奈良", "kind": "災い", "era": "中世", "year": 1428, "title": "正長の土一揆", "text": "近江から広がった土一揆が11月に奈良へ及び、馬借が攻め入った。酒屋・土倉が襲われ、興福寺は徳政令を出した。", "source_url": "https://kotobank.jp/word/正長の土一揆", "source_title": "コトバンク「正長の土一揆」（世界大百科・ニッポニカ・マイペディア）"}, {"pref": "奈良", "kind": "災い", "era": "中世", "year": 1567, "title": "東大寺大仏殿の焼失", "text": "松永久秀と三好三人衆の争いで、東大寺に陣取った三好方を久秀が攻め、大仏殿が焼けた。", "source_url": "https://kotobank.jp/word/松永久秀", "source_title": "コトバンク「松永久秀」（ニッポニカ・世界大百科・山川ほか）"}, {"pref": "奈良", "kind": "災い", "era": "明治", "year": 1889, "title": "十津川大水害", "text": "8月、紀伊半島南部に3日3晩の集中豪雨が降り、十津川村で山崩れが相次いだ。土砂が谷を埋め、各地に湖ができた。", "source_url": "https://www.kkr.mlit.go.jp/kinan/river/kumano_kondan/PDF/information_panel/19.pdf", "source_title": "国交省近畿地方整備局 紀南河川国道事務所 パネル「十津川大水害について」"}, {"pref": "奈良", "kind": "道がひらく", "era": "大正", "year": 1914, "title": "大軌奈良駅の開業", "text": "大阪電気軌道は苦しい工事を経て生駒トンネルを掘り抜き、上本町（大阪）から奈良までの線路を通した。", "source_url": "https://www.library.pref.nara.jp/supporter/naraweb/2023kikakuten-nara150nen/◎大正時代.pdf", "source_title": "奈良県立図書情報館 企画展パネル「大正時代」"}, {"pref": "奈良", "kind": "道がひらく", "era": "大正", "year": 1917, "title": "奈良県初のバス", "text": "奈良県で最初のバスは、松山自動車商会が宇陀郡の松山町と桜井の間に走らせたものだった。", "source_url": "https://www.library.pref.nara.jp/supporter/naraweb/2023kikakuten-nara150nen/◎大正時代.pdf", "source_title": "奈良県立図書情報館 企画展パネル「大正時代」"}, {"pref": "佐賀", "kind": "災い", "era": "平安", "year": 1019, "title": "刀伊の入寇", "text": "大陸の刀伊の賊が対馬・壱岐・筑前を襲い、最後に肥前の松浦郡にも来襲したが、現地の武力に退けられた。", "source_url": "https://kotobank.jp/word/刀伊の入寇", "source_title": "コトバンク「刀伊の入寇」（世界大百科）"}, {"pref": "佐賀", "kind": "恵み", "era": "江戸", "year": 1616, "title": "有田焼の始まり", "text": "伝承では、文禄・慶長の役のあと鍋島氏が連れ帰った李参平ら朝鮮の陶工が、有田で磁器を焼き始めたという。", "source_url": "https://kotobank.jp/word/有田焼", "source_title": "コトバンク「有田焼」（大辞泉・世界大百科）"}, {"pref": "佐賀", "kind": "災い", "era": "明治", "year": 1874, "title": "佐賀の乱", "text": "江藤新平・島義勇を担いだ佐賀の不平士族が挙兵して県庁を占拠したが、大久保利通の指揮する政府軍に鎮圧された。", "source_url": "https://kotobank.jp/word/佐賀の乱", "source_title": "コトバンク「佐賀の乱」（世界大百科・ニッポニカ・山川ほか）"}, {"pref": "佐賀", "kind": "災い", "era": "大正", "year": 1918, "title": "米騒動と炭鉱の暴動", "text": "米騒動の波が佐賀県の炭鉱にも及び、相知炭鉱では民衆と軍隊・警察が激しく衝突した。", "source_url": "https://kotobank.jp/word/米騒動", "source_title": "コトバンク「米騒動」（世界大百科）"}, {"pref": "佐賀", "kind": "恵み", "era": "昭和", "year": 1929, "title": "杵島炭鉱が県下最大に", "text": "杵島炭鉱が佐賀炭鉱を買い取り、本拠を大町に移して第四坑を開いた。以後、県下最大の炭鉱となる。", "source_url": "https://kotobank.jp/word/杵島炭鉱", "source_title": "コトバンク「杵島炭鉱」（ニッポニカ）"}, {"pref": "大分", "kind": "災い", "era": "平安", "year": 1181, "title": "豊後武士団の反平氏挙兵", "text": "国主藤原頼輔・頼経の命を受けて、緒方惟栄ら豊後の武士団が平氏に背いて兵を挙げた。", "source_url": "https://kotobank.jp/word/豊後国", "source_title": "コトバンク「豊後国」（世界大百科）"}, {"pref": "大分", "kind": "災い", "era": "平安", "year": 1184, "title": "宇佐八幡宮の焼打ち", "text": "反平氏の兵を挙げていた緒方惟栄が、7月に宇佐八幡宮を焼き打ちした。", "source_url": "https://kotobank.jp/word/豊後国", "source_title": "コトバンク「豊後国」（世界大百科）"}, {"pref": "大分", "kind": "災い", "era": "中世", "year": 1586, "title": "島津氏による府内焼失", "text": "大友宗麟のもとで貿易港として栄えた府内が、攻め込んだ島津氏によって焼き払われた。", "source_url": "https://kotobank.jp/word/府内", "source_title": "コトバンク「府内」（ニッポニカ・旺文社）"}, {"pref": "大分", "kind": "災い", "era": "江戸", "year": 1811, "title": "岡藩文化大一揆", "text": "岡藩の増税策「新法」に反発した領民が打ちこわしを伴う一揆を起こし、翌年にかけて豊後一円と豊前に広がった。", "source_url": "https://kotobank.jp/word/岡藩", "source_title": "コトバンク「岡藩」（ニッポニカ）・「豊後国」（世界大百科）"}, {"pref": "大分", "kind": "道がひらく", "era": "明治", "year": 1911, "title": "鉄道が大分に達する", "text": "延長を重ねてきた鉄道が、柳ヶ浦―大分間の開通でついに大分に達した。のちの日豊本線である。", "source_url": "https://kotobank.jp/word/日豊本線", "source_title": "コトバンク「日豊本線」（ニッポニカ・世界大百科・ブリタニカ）"}, {"pref": "大分", "kind": "恵み", "era": "明治", "year": 1911, "title": "大分市の誕生", "text": "明治4年に県庁所在地となってからも発展が遅れていた大分に、市制が施行され大分市が生まれた。", "source_url": "https://kotobank.jp/word/大分市", "source_title": "コトバンク「大分市」（ブリタニカ）"}, {"pref": "大分", "kind": "災い", "era": "昭和", "year": 1945, "title": "大分空襲", "text": "3月に最初の空襲があった。7月16日の夜ふけからの空襲ではおよそ6000発の焼夷弾が落ち、町の中心は焼け野原になった。", "source_url": "https://www.city.oita.oita.jp/o029/shisejoho/kohokocho/koho/shihooita/documents/202508_part2.pdf", "source_title": "市報おおいた 令和7年8月号「終戦80年と私たちの役割」"}];
if (typeof module !== 'undefined') module.exports = EVENTS; else g.JOZO_EVENTS = EVENTS; })(this);
